window.AUTH=window.AUTH||{};window.AUTH["25-842"]={"d":"25-842","id":"2026/25-842","n":"Wassily v. Blanche","briefs":[{"k":"petitioner","label":"Brief of petitioners","date":"2026-08-24","url":"https://www.supremecourt.gov/DocketPDF/25/25-842/419950/20260824144814634_2026-08-24%20Wassily-Velasquez%20SCT%20No.%2025-842%20-%20Merits%20Brief%20with%20addendum.pdf","side":"pet","n":114},{"k":"respondent","label":"Brief of respondent Todd Blanche, Attorney General","date":"2026-10-02","url":"https://www.supremecourt.gov/DocketPDF/25/25-842/428396/20261002195824636_Wassily_respondent_brief.pdf","side":"res","n":75},{"k":"reply","label":"Reply of petitioners Tamer S. Wassily, et al.","date":"2026-11-02","url":"https://www.supremecourt.gov/DocketPDF/25/25-842/431511/20261102133158653_2026-11-02%20S.Ct.%20No.%2025-842%20%20Wassily_Velasquez%20Merits%20Reply%20Brief.pdf","side":"pet","n":68}],"opinion":null,"tr":false,"items":[{"t":"case","label":"Ali v. Achim","cite":"468 F.3d 462","y":2006,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/468/462/","by":{"0":"6, 37"}},{"t":"case","label":"Ali v. Federal Bureau of Prisons","cite":"552 U.S. 214","y":2008,"id":"2007/06-9130","sc":1,"sum":"The Court agreed with the 11th Circuit and, in a 5-4 majority opinion written by Justice Clarence Thomas, held that the use of the word \"any\" should be given its normal interpretation, encompassing all federal officers whether or not they were involved in enforcing customs or excise laws.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Barber v. Gonzales","cite":"347 U.S. 637","y":1954,"id":"scdb/1953-081","sc":1,"sum":"He may not now be deported under § 19 (a) of the Immigration Act of 1917 as an alien who had been so sentenced \"after entry.\"","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41"}},{"t":"case","label":"Becerra v. Empire Health Foundation for Valley Hospital Medical Center","cite":"597 U.S. 424","y":2022,"id":"2021/20-1312","sc":1,"sum":"For purposes of calculating the Medicare fraction—one of two fractions the Medicare program uses to adjust the rates paid to hospitals that serve a higher-than-usual percentage of low-income patients—those individuals “entitled to [Medicare Part A] benefits” are all those qualifying for the program, regardless of whether they receive Medicare payments for part or all of a hospital stay.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"34"}},{"t":"case","label":"BNSF Railway Co. v. Loos","cite":"586 U.S. 310","y":2019,"id":"2018/17-1042","sc":1,"sum":"A railroad’s payment to an employee for working time lost due to an on-the-job injury is taxable “compensation” under the Railroad Retirement Tax Act.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"27"}},{"t":"case","label":"Board of Trustees of the Leland Stanford Junior University v. Roche Molecular Systems, Inc.","cite":"563 U.S. 776","y":2011,"id":"2010/09-1159","sc":1,"sum":"The Court held that patents on inventions that arise from federally-funded research do not automatically go to university where the inventor worked.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Boechler, P.C. v. Commissioner","cite":"596 U.S. 199","y":2022,"id":"2021/20-1472","sc":1,"sum":"The 30-day time limit to file a petition for review of a collection due process determination, 26 U. S. C. §6330(d)(1), is a nonjurisdictional deadline subject to equitable tolling.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"34"}},{"t":"case","label":"Bonetti v. Rogers","cite":"356 U.S. 691","y":1958,"id":"1957/94","sc":1,"sum":"Since petitioner's\" claim of right to remain in the United States is based upon his entry in 1938 and he was not then and has not since been a member of the Communist Party, he is not deportable under §§ 1 and4 (a).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41"}},{"t":"case","label":"Bostock v. Clayton County","cite":"590 U.S. 644","y":2020,"id":"2019/17-1618","sc":1,"sum":"The Court held that Title VII of the Civil Rights Act of 1964, which prohibits against employment discrimination “because of . . . sex” encompasses discrimination based on an individual’s sexual orientation.","sumSrc":"Oyez","by":{"0":"35","1":"29","2":"20"}},{"t":"case","label":"Castillo v. Bondi","cite":"140 F.4th 777","y":2025,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/140/777/","by":{"0":"41"}},{"t":"case","label":"Page(s) Cela v. Garland","cite":"75 F.4th 355","y":2023,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/75/355/","by":{"0":"9, 11, 21, 22, 42","1":"8, 13","2":"12"}},{"t":"case","label":"Costello v. INS","cite":"376 U.S. 120","y":1964,"id":"1963/83","sc":1,"sum":"Petitioner, while a naturalized citizen, was convicted of two separate offenses involving moral turpitude. Following his subsequent denaturalization on the ground that his citizenship had been acquired by willful misrepresentation, proceedings were brought against him under § 241 (a) (4) of the Immigration and Nationality Act of 1952, which provides for deportation of an alien who at any time after entry \"is …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41"}},{"t":"case","label":"Dada v. Mukasey","cite":"554 U.S. 1","y":2008,"id":"2007/06-1181","sc":1,"sum":"Justice Anthony Kennedy, joined by four other Justices, stated that an alien has two options in such a case: he may abide by the terms of the voluntary departure and leave the country on time, maintaining the re-entry perks, or withdraw the voluntary departure request and remain in the country to pursue the motion to reopen. If the alien chooses the second option, he may become subject to deportation proceedings.","sumSrc":"Oyez","by":{"0":"41, 43","1":"39","2":"22"}},{"t":"case","label":"Esquivel-Quintana v. Sessions","cite":"581 U.S. 385","y":2017,"id":"2016/16-54","sc":1,"sum":"The Court determined that the crime of “unlawful sexual intercourse with a minor” as defined by California law cannot be categorically considered the aggravated felony of “sexual abuse of a minor” for the purpose of mandatory removal under the Immigration and Nationality Act (INA).","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"Florida Department of Revenue v. Piccadilly Cafeterias, Inc.","cite":"554 U.S. 33","y":2008,"id":"2007/07-312","sc":1,"sum":"The Court held 7-2 that the plain meaning of the statute indicates that it only applies to confirmed asset sales, not \"pre-confirmation\" sales.","sumSrc":"Oyez","by":{"0":"16, 17","1":"12","2":"3, 18"}},{"t":"case","label":"Fong Haw Tan v. Phelan","cite":"333 U.S. 6","y":1948,"id":"scdb/1947-030","sc":1,"sum":"1. Section 19 (a) of the Immigration Act of 1917, as hiended, which provides that an alien who is \"sentenced more than once\" to imprisonment for a term of one year or more because of conviction of a crime involving moral turpitude committed after entn, shall be deported, does not apply to an alien who, in a single trial, has been convicted on two different counts of a single indictment for murdering two different …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40, 41","1":"38","2":"22"}},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"582 U.S. 79","y":2017,"id":"2016/16-349","sc":1,"sum":"The Court determined that a party that purchases a debt and attempts to collect the debt for its own account is not a “debt collector” subject to the Fair Debt Collection Practices Act (FDCPA).","sumSrc":"Oyez","by":{"0":"18","1":"12","2":"3"}},{"t":"case","label":"IBP, Inc. v. Alvarez","cite":"546 U.S. 21","y":2005,"id":"2005/03-1238","sc":1,"sum":"Justice John Paul Stevens, for a unanimous Court, wrote that putting on required safety equipment qualified as a \"principal activity\" under the FLSA. The workday began when employees started that activity and therefore included the subsequent time spent walking to the worksite.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"INS v. Cardoza-Fonseca","cite":"480 U.S. 421","y":1987,"id":"1986/85-782","sc":1,"sum":"The §243(h) \"clear probability\" standard of proof does not govern asylum applications under §208(a).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28, 40, 41, 43","1":"19, 38","2":"22, 23"}},{"t":"case","label":"INS v. Errico","cite":"385 U.S. 214","y":1966,"id":"1966/54","sc":1,"sum":"Section 241 (f) of the Immigration and Nationality Act, which exempts from deportation an alien who obtained a visa and entry to the United States by fraud and misrepresentation where the alien is the spouse, parent or child of an American citizen or of an alien lawfully admitted for permanent residence, and was \"otherwise admissible at the time of entry,\" is construed, in the light of its humanitarian purpose of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41, 43","1":"38, 39","2":"22, 23"}},{"t":"case","label":"INS v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"sum":"The Court held that habeas jurisdiction was not repealed by AEDPA and IIRIRA.","sumSrc":"Oyez","by":{"0":"41, 43","1":"38, 39","2":"22, 23"}},{"t":"case","label":"Page(s) Jeudy v. Holder","cite":"768 F.3d 595","y":2014,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/768/595/","by":{"0":"43"}},{"t":"case","label":"Kawashima v. Holder","cite":"565 U.S. 478","y":2012,"id":"2011/10-577","sc":1,"sum":"The Court held that filing a false tax return in violation of 26 U.S.C. Section 7206 qualifies as an aggravated felony under the Immigration and Nationality Act if the Government's revenue loss exceeds $10,000.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"Lennon v. INS","cite":"527 F.2d 187","y":1975,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/527/187/","by":{"0":"44"}},{"t":"case","label":"Leocal v. Ashcroft","cite":"543 U.S. 1","y":2004,"id":"2004/03-583","sc":1,"sum":"The Court held that state DUI offenses, except when involving purposeful intent, are accidental and not crimes of violence under federal law. Le therefore did not commit an aggravated felony for which he could be deported.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"Lok v. INS","cite":"548 F.2d 37","y":1977,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/548/37/","sum":"Observing that the rule is “especially pertinent” in cases involving relief from deportation.","sumSrc":"brief:0","by":{"0":"43"}},{"t":"case","label":"Loper Bright Enterprises v. Raimondo","cite":"603 U.S. 369","y":2024,"id":"2023/22-451","sc":1,"sum":"The Administrative Procedure Act requires courts to exercise their independent judgment in deciding whether an agency has acted within its statutory authority, and courts may not defer to an agency interpretation of the law simply because a statute is ambiguous; Chevron U. S. A. Inc. v. Natural Resources Defense Council, Inc., 467 U. S. 837, is overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"41"}},{"t":"case","label":"M&K Employee Solutions, LLC v. Trustees of the IAM National Pension Fund","cite":"146 S. Ct. 1224","y":2026,"id":"2025/23-1209","sc":1,"sum":"The Court held that under the Employee Retirement Income Security Act (ERISA), pension plans may calculate an employer's withdrawal liability using actuarial assumptions selected after the statutory measurement date (the last day of the plan year before the employer's withdrawal).","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Marques v. Lynch","cite":"834 F.3d 549","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/834/549/","by":{"0":"27"}},{"t":"case","label":"Ministry of Defense & Support for the Armed Forces of the Islamic Republic of Iran v. Elahi","cite":"556 U.S. 366","y":2009,"id":"2008/07-615","sc":1,"sum":"The Court held that the defendant's assets in question were not \"blocked\" under the Terrorism Risk Insurance Act of 2002 and therefore could not be attached to satisfy his judgment against Iran.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Monsalvo v. Bondi","cite":"604 U.S. 712","y":2025,"url":"https://supreme.justia.com/cases/federal/us/604/712/","sc":1,"by":{"0":"25"}},{"t":"case","label":"Mullin v. Al Otro Lado","cite":"146 S. Ct. 2079","y":2026,"url":"https://www.courtlistener.com/c/S.%20Ct./146/2079/","sc":1,"by":{"0":"23"}},{"t":"case","label":"Page(s) Nethagani v. Mukasey","cite":"532 F.3d 150","y":2008,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/532/150/","by":{"0":"6, 37"}},{"t":"case","label":"O’Gilvie v. United States","cite":"519 U.S. 79","y":1996,"id":"1996/95-966","sc":1,"sum":"The Court held that the punitive damages received by the O'Gilvies were not received \"on account of\" personal injuries,\" and therefore the provision did not apply and the damages were taxable.","sumSrc":"Oyez","by":{"0":"35","1":"29","2":"20"}},{"t":"case","label":"Padash v. INS","cite":"358 F.3d 1161","y":2004,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/358/1161/","by":{"0":"43"}},{"t":"case","label":"Padilla v. Kentucky","cite":"559 U.S. 356","y":2010,"id":"2009/08-651","sc":1,"sum":"The Court held that counsel must inform a client whether or not his plea carries a risk of deportation under the Sixth Amendment.","sumSrc":"Oyez","by":{"0":"37, 42"}},{"t":"case","label":"Powerex Corp. v. Reliant Energy Services, Inc.","cite":"551 U.S. 224","y":2007,"id":"2006/05-85","sc":1,"sum":"The Court ruled 7-2 that the Ninth Circuit lacked jurisdiction to review the District Court's remand order. The Court relied on 28 U.S.C. 1447(d), which precludes appellate review of remands based on lack of subject-matter jurisdiction.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Pulsifer v. United States","cite":"601 U.S. 124","y":2024,"id":"2023/22-340","sc":1,"sum":"A criminal defendant facing a mandatory minimum sentence is eligible for safety-valve relief under 18 U. S. C. §3553(f)(1) only if the defendant satisfies each of the provision’s three conditions.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"39"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Saldivar v. Sessions","cite":"877 F.3d 812","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/877/812/","by":{"0":"20"}},{"t":"case","label":"Sessions v. Dimaya","cite":"584 U.S. 148","y":2018,"id":"2017/15-1498","sc":1,"sum":"A case in which the Court struck down the Immigration and Nationality Act’s “crime of violence” provision as unconstitutionally vague in violation of the Due Process Clause of the Fifth Amendment.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"Simmons v. Himmelreich","cite":"578 U.S. 621","y":2016,"id":"2015/15-109","sc":1,"sum":"The Court determined that the judgment bar of the Federal Tort Claims Act (FTCA) does not apply to claims dismissed for falling under the exceptions to the FTCA.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Siwe v. Holder","cite":"742 F.3d 603","y":2014,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/742/603/","by":{"0":"22, 24, 42"}},{"t":"case","label":"Page(s) Snyder v. United States","cite":"603 U.S. 1","y":2024,"url":"https://supreme.justia.com/cases/federal/us/603/1/","sc":1,"by":{"0":"34"}},{"t":"case","label":"Southwest Airlines Co. v. Saxon","cite":"596 U.S. 450","y":2022,"id":"2021/21-309","sc":1,"sum":"Airplane cargo loaders and ramp supervisors who, like petitioner Saxon, frequently load and unload airplane cargo belong to a “class of workers engaged in foreign or interstate commerce” exempt from the Federal Arbitration Act’s coverage.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"21"}},{"t":"case","label":"Tula-Rubio v. Lynch","cite":"787 F.3d 288","y":2015,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/787/288/","sum":"Recognizing that “status” “encompasses both lawful and unlawful legal conditions” (emphasis omitted).","sumSrc":"brief:0","by":{"0":"19"}},{"t":"case","label":"United States v. Christopher","cite":"239 F.3d 1191","y":2001,"url":"https://www.courtlistener.com/c/F.3d/239/1191/","by":{"0":"38"}},{"t":"case","label":"United States v. Gonzales","cite":"520 U.S. 1","y":1997,"id":"1996/95-1605","sc":1,"sum":"In a 7-to-2 decision delivered by Justice Sandra Day O'Connor, the Court announced \"[t]he plain language of (the law) forbids a district court to direct that a term of imprisonment under the statute run concurrently with any other term of imprisonment, whether state or federal.\".","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"United States v. Graham","cite":"169 F.3d 787","y":1999,"url":"https://www.courtlistener.com/c/F.3d/169/787/","by":{"0":"38"}},{"t":"case","label":"United States v. Hansen","cite":"599 U.S. 762","y":2023,"id":"2022/22-179","sc":1,"sum":"Title 8 U. S. C. §1324(a)(1)(A)(iv)—which criminalizes “encouraging or inducing” illegal immigration—forbids only the purposeful solicitation and facilitation of specific acts known to violate federal law and is not unconstitutionally overbroad.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"24, 27"}},{"t":"case","label":"United States v. Pacheco","cite":"225 F.3d 148","y":2000,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/225/148/","by":{"0":"37"}},{"t":"case","label":"United States v. Wilson","cite":"503 U.S. 329","y":1992,"id":"1991/90-1745","sc":1,"sum":"It is the Attorney General who computes the amount of the § 3585(b) credit after the defendant has begun to serve his sentence.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"Page(s) Velásquez-García v. Holder","cite":"760 F.3d 571","y":2014,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/760/571/","by":{"0":"43"}},{"t":"case","label":"Wassily v. Holder","cite":"523 F. App’x 783","y":2013,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/523/783/","by":{"0":"7"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","subs":["(a)(15)(A)(iii)","(a)(42)(A)","(a)(20)"],"stext":{"head":"§1101. Definitions","paras":[[0,"(a) As used in this chapter—"],[0,"(1) The term \"administrator\" means the official designated by the Secretary of State pursuant to section 1104(b) of this title."],[0,"(2) The term \"advocates\" includes, but is not limited to, advises, recommends, furthers by overt act, and admits belief in."],[0,"(3) The term \"alien\" means any person not a citizen or national of the United States."],[0,"(4) The term \"application for admission\" has reference to the application for admission into the United States and not to the application for the issuance of an immigrant or nonimmigrant visa."],[0,"(5) The term \"Attorney General\" means the Attorney General of the United States."],[0,"(6) The term \"border crossing identification card\" means a document of identity bearing that designation issued to an alien who is lawfully admitted for permanent residence, or to an alien who is a resident in foreign contiguous territory, by a consular officer or an immigration officer for the purpose of crossing over the borders between the United States and foreign contiguous territory in accordance with such conditions for its issuance and use as may be prescribed by regulations. Such regulations shall provide that (A) each such document include a biometric identifier (such as the fingerprint or handprint of the alien) that is machine readable and (B) an alien presenting a border crossing identification card is not permitted to cross over the border into the United States unless the biometric identifier contained on the card matches the appropriate biometric characteristic of the alien."],[0,"(7) The term \"clerk of court\" means a clerk of a naturalization court."],[0,"(8) The terms \"Commissioner\" and \"Deputy Commissioner\" mean the Commissioner of Immigration and Naturalization and a Deputy Commissioner of Immigration and Naturalization, respectively."],[0,"(9) The term \"consular officer\" means any consular, diplomatic, or other officer or employee of the United States designated under regulations prescribed under authority contained in this chapter, for the purpose of issuing immigrant or nonimmigrant visas or, when used in subchapter III, for the purpose of adjudicating nationality."],[0,"(10) The term \"crewman\" means a person serving in any capacity on board a vessel or aircraft."],[0,"(11) The term \"diplomatic visa\" means a nonimmigrant visa bearing that title and issued to a nonimmigrant in accordance with such regulations as the Secretary of State may prescribe."],[0,"(12) The term \"doctrine\" includes, but is not limited to, policies, practices, purposes, aims, or procedures."],[0,"(13)(A) The terms \"admission\" and \"admitted\" mean, with respect to an alien, the lawful entry of the alien into the United States after inspection and authorization by an immigration officer."],[0,"(B) An alien who is paroled under section 1182(d)(5) of this title or permitted to land temporarily as an alien crewman shall not be considered to have been admitted."],[0,"(C) An alien lawfully admitted for permanent residence in the United States shall not be regarded as seeking an admission into the United States for purposes of the immigration laws unless the alien—"],[1,"(i) has abandoned or relinquished that status,"],[1,"(ii) has been absent from the United States for a continuous period in excess of 180 days,"],[1,"(iii) has engaged in illegal activity after having departed the United States,"],[1,"(iv) has departed from the United States while under legal process seeking removal of the alien from the United States, including removal proceedings under this chapter and extradition proceedings,"],[1,"(v) has committed an offense identified in section 1182(a)(2) of this title, unless since such offense the alien has been granted relief under section 1182(h) or 1229b(a) of this title, or"],[1,"(vi) is attempting to enter at a time or place other than as designated by immigration officers or has not been admitted to the United States after inspection and authorization by an immigration officer."],[0,"(14) The term \"foreign state\" includes outlying possessions of a foreign state, but self-governing dominions or territories under mandate or trusteeship shall be regarded as separate foreign states."],[0,"(15) The term \"immigrant\" means every alien except an alien who is within one of the following classes of nonimmigrant aliens—"],[1,"(A)(i) an ambassador, public minister, or career diplomatic or consular officer who has been accredited by a foreign government, recognized de jure by the United States and who is accepted by the President or by the Secretary of State, and the members of the alien's immediate family;"],[1,"(ii) upon a basis of reciprocity, other officials and employees who have been accredited by a foreign government recognized de jure by the United States, who are accepted by the Secretary of State, and the members of their immediate families; and"],[1,"(iii) upon a basis of reciprocity, attendants, servants, personal employees, and members of their immediate families, of the officials and employees who have a nonimmigrant status under (i) and (ii) above;"],[1,"(B) an alien (other than one coming for the purpose of study or of performing skilled or unskilled labor or as a representative of foreign press, radio, film, or other foreign information media coming to engage in such vocation) having a residence in a foreign country which he has no intention of abandoning and who is visiting the United States temporarily for business or temporarily for pleasure;"],[1,"(C)(i) an alien in immediate and continuous transit through the United States, for a period not to exceed 29 days;"],[1,"(ii) an alien who qualifies as a person entitled to pass in transit to and from the United Nations Headquarters District (as defined in section 4309a(e) of title 22) and foreign countries, under the provisions of paragraphs (3), (4), and (5) of section 11 of the Agreement regarding the Headquarters of the United Nations, done at Lake Success June 26, 1947 (61 Stat. 758); or"],[1,"(iii) an alien passing in transit through the United States to board a vessel on which the alien will perform, or to disembark from a vessel on which the alien performed, ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, for a period not to exceed 180 days;"],[1,"(D)(i) an alien crewman serving in good faith as such in a capacity required for normal operation and service on board a vessel, as defined in section 1288(a) of this title (other than a fishing vessel having its home port or an operating base in the United States), or aircraft, who intends to land temporarily and solely in pursuit of his calling as a crewman and to depart from the United States with the vessel or aircraft on which he arrived or some other vessel or aircraft;"],[1,"(ii) an alien crewman serving in good faith as such in any capacity required for normal operations and service aboard a fishing vessel having its home port or an operating base in the United States who intends to land temporarily in Guam or the Commonwealth of the Northern Mariana Islands and solely in pursuit of his calling as a crewman and to depart from Guam or the Commonwealth of the Northern Mariana Islands with the vessel on which he arrived; or"],[1,"(iii) an alien crewman performing ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, who intends to land temporarily solely in pursuit of the alien's responsibilities as a crewman and to depart from the United States on the vessel on which the alien arrived or on another vessel or aircraft, for a period not to exceed 180 days;"],[1,"(E) an alien entitled to enter the United States under and in pursuance of the provisions of a treaty of commerce and navigation between the United States and the foreign state of which the alien is a national (or, in the case of an alien who acquired the relevant nationality through a financial investment and who has not previously been granted status under this subparagraph, the foreign state of which the alien is a national and in which the alien has been domiciled for a continuous period of not less than 3 years at any point before applying for a nonimmigrant visa under this subparagraph), and the spouse and children of any such alien if accompanying or following to join such alien; (i) solely to carry on substantial trade, including trade in services or trade in technology, principally between the United States and the foreign state of which the alien is a national; (ii) solely to develop and direct the operations of an enterprise in which the alien has invested, or of an enterprise in which the alien is actively in the process of investing, a substantial amount of capital; or (iii) solely to perform services in a specialty occupation in the United States if the alien is a national of the Commonwealth of Australia and with respect to whom the Secretary of Labor determines and certifies to the Secretary of Homeland Security and the Secretary of State that the intending employer has filed with the Secretary of Labor an attestation under section 1182(t)(1) of this title;"],[1,"(F)(i) an alien having a residence in a foreign country which he has no intention of abandoning, who is a bona fide student qualified to pursue a full course of study and who seeks to enter the United States temporarily and solely for the purpose of pursuing such a course of study consistent with section 1184(l) 1 of this title at an established college, university, seminary, conservatory, academic high school, elementary school, or other academic institution or in an accredited language training program in the United States, particularly designated by him and approved by the Attorney General after consultation with the Secretary of Education, which institution or place of study shall have agreed to report to the Attorney General the termination of attendance of each nonimmigrant student, and if any such institution of learning or place of study fails to make reports promptly the approval shall be withdrawn, (ii) the alien spouse and minor children of any alien described in clause (i) if accompanying or following to join such an alien, and (iii) an alien who is a national of Canada or Mexico, who maintains actual residence and place of abode in the country of nationality, who is described in clause (i) except that the alien's qualifications for and actual course of study may be full or part-time, and who commutes to the United States institution or place of study from Canada or Mexico;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1101?type=usc&year=mostrecent&link-type=html"},"head":"§1101. Definitions","tname":"Aliens and Nationality","by":{"0":"19, 2, 4","1":"2, 3, 15, 13, 3","2":"14"}},{"t":"usc","label":"8 U.S.C. § 1157","url":"https://www.law.cornell.edu/uscode/text/8/1157","subs":["(c)","(c)(4)","(a)(4)"],"stext":{"head":"§1157. Annual admission of refugees and admission of emergency situation refugees","paras":[[0,"(a) Maximum number of admissions; increases for humanitarian concerns; allocations"],[0,"(1) Except as provided in subsection (b), the number of refugees who may be admitted under this section in fiscal year 1980, 1981, or 1982, may not exceed fifty thousand unless the President determines, before the beginning of the fiscal year and after appropriate consultation (as defined in subsection (e)), that admission of a specific number of refugees in excess of such number is justified by humanitarian concerns or is otherwise in the national interest."],[0,"(2) Except as provided in subsection (b), the number of refugees who may be admitted under this section in any fiscal year after fiscal year 1982 shall be such number as the President determines, before the beginning of the fiscal year and after appropriate consultation, is justified by humanitarian concerns or is otherwise in the national interest."],[0,"(3) Admissions under this subsection shall be allocated among refugees of special humanitarian concern to the United States in accordance with a determination made by the President after appropriate consultation."],[0,"(4) In the determination made under this subsection for each fiscal year (beginning with fiscal year 1992), the President shall enumerate, with the respective number of refugees so determined, the number of aliens who were granted asylum in the previous year."],[0,"(b) Determinations by President respecting number of admissions for humanitarian concerns"],[0,"If the President determines, after appropriate consultation, that (1) an unforeseen emergency refugee situation exists, (2) the admission of certain refugees in response to the emergency refugee situation is justified by grave humanitarian concerns or is otherwise in the national interest, and (3) the admission to the United States of these refugees cannot be accomplished under subsection (a), the President may fix a number of refugees to be admitted to the United States during the succeeding period (not to exceed twelve months) in response to the emergency refugee situation and such admissions shall be allocated among refugees of special humanitarian concern to the United States in accordance with a determination made by the President after the appropriate consultation provided under this subsection."],[0,"(c) Admission by Attorney General of refugees; criteria; admission status of spouse or child; applicability of other statutory requirements; termination of refugee status of alien, spouse or child"],[0,"(1) Subject to the numerical limitations established pursuant to subsections (a) and (b), the Attorney General may, in the Attorney General's discretion and pursuant to such regulations as the Attorney General may prescribe, admit any refugee who is not firmly resettled in any foreign country, is determined to be of special humanitarian concern to the United States, and is admissible (except as otherwise provided under paragraph (3)) as an immigrant under this chapter."],[0,"(2)(A) A spouse or child (as defined in section 1101(b)(1)(A), (B), (C), (D), or (E) of this title) of any refugee who qualifies for admission under paragraph (1) shall, if not otherwise entitled to admission under paragraph (1) and if not a person described in the second sentence of section 1101(a)(42) of this title, be entitled to the same admission status as such refugee if accompanying, or following to join, such refugee and if the spouse or child is admissible (except as otherwise provided under paragraph (3)) as an immigrant under this chapter. Upon the spouse's or child's admission to the United States, such admission shall be charged against the numerical limitation established in accordance with the appropriate subsection under which the refugee's admission is charged."],[0,"(B) An unmarried alien who seeks to accompany, or follow to join, a parent granted admission as a refugee under this subsection, and who was under 21 years of age on the date on which such parent applied for refugee status under this section, shall continue to be classified as a child for purposes of this paragraph, if the alien attained 21 years of age after such application was filed but while it was pending."],[0,"(3) The provisions of paragraphs (4), (5), and (7)(A) of section 1182(a) of this title shall not be applicable to any alien seeking admission to the United States under this subsection, and the Attorney General may waive any other provision of such section (other than paragraph (2)(C) or subparagraph (A), (B), (C), or (E) of paragraph (3)) with respect to such an alien for humanitarian purposes, to assure family unity, or when it is otherwise in the public interest. Any such waiver by the Attorney General shall be in writing and shall be granted only on an individual basis following an investigation. The Attorney General shall provide for the annual reporting to Congress of the number of waivers granted under this paragraph in the previous fiscal year and a summary of the reasons for granting such waivers."],[0,"(4) The refugee status of any alien (and of the spouse or child of the alien) may be terminated by the Attorney General pursuant to such regulations as the Attorney General may prescribe if the Attorney General determines that the alien was not in fact a refugee within the meaning of section 1101(a)(42) of this title at the time of the alien's admission."],[0,"(d) Oversight reporting and consultation requirements"],[0,"(1) Before the start of each fiscal year the President shall report to the Committees on the Judiciary of the House of Representatives and of the Senate regarding the foreseeable number of refugees who will be in need of resettlement during the fiscal year and the anticipated allocation of refugee admissions during the fiscal year. The President shall provide for periodic discussions between designated representatives of the President and members of such committees regarding changes in the worldwide refugee situation, the progress of refugee admissions, and the possible need for adjustments in the allocation of admissions among refugees."],[0,"(2) As soon as possible after representatives of the President initiate appropriate consultation with respect to the number of refugee admissions under subsection (a) or with respect to the admission of refugees in response to an emergency refugee situation under subsection (b), the Committees on the Judiciary of the House of Representatives and of the Senate shall cause to have printed in the Congressional Record the substance of such consultation."],[0,"(3)(A) After the President initiates appropriate consultation prior to making a determination under subsection (a), a hearing to review the proposed determination shall be held unless public disclosure of the details of the proposal would jeopardize the lives or safety of individuals."],[0,"(B) After the President initiates appropriate consultation prior to making a determination, under subsection (b), that the number of refugee admissions should be increased because of an unforeseen emergency refugee situation, to the extent that time and the nature of the emergency refugee situation permit, a hearing to review the proposal to increase refugee admissions shall be held unless public disclosure of the details of the proposal would jeopardize the lives or safety of individuals."],[0,"(e) \"Appropriate consultation\" defined"],[0,"For purposes of this section, the term \"appropriate consultation\" means, with respect to the admission of refugees and allocation of refugee admissions, discussions in person by designated Cabinet-level representatives of the President with members of the Committees on the Judiciary of the Senate and of the House of Representatives to review the refugee situation or emergency refugee situation, to project the extent of possible participation of the United States therein, to discuss the reasons for believing that the proposed admission of refugees is justified by humanitarian concerns or grave humanitarian concerns or is otherwise in the national interest, and to provide such members with the following information:"],[1,"(1) A description of the nature of the refugee situation."],[1,"(2) A description of the number and allocation of the refugees to be admitted and an analysis of conditions within the countries from which they came."],[1,"(3) A description of the proposed plans for their movement and resettlement and the estimated cost of their movement and resettlement."],[1,"(4) An analysis of the anticipated social, economic, and demographic impact of their admission to the United States."],[1,"(5) A description of the extent to which other countries will admit and assist in the resettlement of such refugees."],[1,"(6) An analysis of the impact of the participation of the United States in the resettlement of such refugees on the foreign policy interests of the United States."],[1,"(7) Such additional information as may be appropriate or requested by such members."],[0,"To the extent possible, information described in this subsection shall be provided at least two weeks in advance of discussions in person by designated representatives of the President with such members."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1157?type=usc&year=mostrecent&link-type=html"},"head":"§1157. Annual admission of refugees and admission of emergency situation refugees","tname":"Aliens and Nationality","by":{"0":"4, 5","1":"3, 23, 37","2":"4"}},{"t":"usc","label":"8 U.S.C. § 1158","url":"https://www.law.cornell.edu/uscode/text/8/1158","subs":["(a)","(b)(2)","(b)(2)(A)(ii)","(b)(2)(A)(vi)","(b)(2)(B)(i)","(b)(2)(B)(ii)","(b)(3)(A)","(c)(1)","(c)(2)","(c)(2)(A)","(c)(2)(B)","(c)(2)(C)","(c)(2)(E)","(c)(3)","(d)(3)","(a)(1)","(a)(2)","(b)(1)(A)","(c)","(c)(1)(A)"],"stext":{"head":"§1158. Asylum","paras":[[0,"(a) Authority to apply for asylum"],[0,"(1) In general"],[1,"Any alien who is physically present in the United States or who arrives in the United States (whether or not at a designated port of arrival and including an alien who is brought to the United States after having been interdicted in international or United States waters), irrespective of such alien's status, may apply for asylum in accordance with this section or, where applicable, section 1225(b) of this title."],[0,"(2) Exceptions"],[0,"(A) Safe third country"],[2,"Paragraph (1) shall not apply to an alien if the Attorney General determines that the alien may be removed, pursuant to a bilateral or multilateral agreement, to a country (other than the country of the alien's nationality or, in the case of an alien having no nationality, the country of the alien's last habitual residence) in which the alien's life or freedom would not be threatened on account of race, religion, nationality, membership in a particular social group, or political opinion, and where the alien would have access to a full and fair procedure for determining a claim to asylum or equivalent temporary protection, unless the Attorney General finds that it is in the public interest for the alien to receive asylum in the United States."],[0,"(B) Time limit"],[2,"Subject to subparagraph (D), paragraph (1) shall not apply to an alien unless the alien demonstrates by clear and convincing evidence that the application has been filed within 1 year after the date of the alien's arrival in the United States."],[0,"(C) Previous asylum applications"],[2,"Subject to subparagraph (D), paragraph (1) shall not apply to an alien if the alien has previously applied for asylum and had such application denied."],[0,"(D) Changed circumstances"],[2,"An application for asylum of an alien may be considered, notwithstanding subparagraphs (B) and (C), if the alien demonstrates to the satisfaction of the Attorney General either the existence of changed circumstances which materially affect the applicant's eligibility for asylum or extraordinary circumstances relating to the delay in filing an application within the period specified in subparagraph (B)."],[0,"(E) Applicability"],[2,"Subparagraphs (A) and (B) shall not apply to an unaccompanied alien child (as defined in section 279(g) of title 6)."],[0,"(3) Limitation on judicial review"],[1,"No court shall have jurisdiction to review any determination of the Attorney General under paragraph (2)."],[0,"(b) Conditions for granting asylum"],[0,"(1) In general"],[0,"(A) Eligibility"],[2,"The Secretary of Homeland Security or the Attorney General may grant asylum to an alien who has applied for asylum in accordance with the requirements and procedures established by the Secretary of Homeland Security or the Attorney General under this section if the Secretary of Homeland Security or the Attorney General determines that such alien is a refugee within the meaning of section 1101(a)(42)(A) of this title."],[0,"(B) Burden of proof"],[0,"(i) In general"],[3,"The burden of proof is on the applicant to establish that the applicant is a refugee, within the meaning of section 1101(a)(42)(A) of this title. To establish that the applicant is a refugee within the meaning of such section, the applicant must establish that race, religion, nationality, membership in a particular social group, or political opinion was or will be at least one central reason for persecuting the applicant."],[0,"(ii) Sustaining burden"],[3,"The testimony of the applicant may be sufficient to sustain the applicant's burden without corroboration, but only if the applicant satisfies the trier of fact that the applicant's testimony is credible, is persuasive, and refers to specific facts sufficient to demonstrate that the applicant is a refugee. In determining whether the applicant has met the applicant's burden, the trier of fact may weigh the credible testimony along with other evidence of record. Where the trier of fact determines that the applicant should provide evidence that corroborates otherwise credible testimony, such evidence must be provided unless the applicant does not have the evidence and cannot reasonably obtain the evidence."],[0,"(iii) Credibility determination"],[3,"Considering the totality of the circumstances, and all relevant factors, a trier of fact may base a credibility determination on the demeanor, candor, or responsiveness of the applicant or witness, the inherent plausibility of the applicant's or witness's account, the consistency between the applicant's or witness's written and oral statements (whenever made and whether or not under oath, and considering the circumstances under which the statements were made), the internal consistency of each such statement, the consistency of such statements with other evidence of record (including the reports of the Department of State on country conditions), and any inaccuracies or falsehoods in such statements, without regard to whether an inconsistency, inaccuracy, or falsehood goes to the heart of the applicant's claim, or any other relevant factor. There is no presumption of credibility, however, if no adverse credibility determination is explicitly made, the applicant or witness shall have a rebuttable presumption of credibility on appeal."],[0,"(2) Exceptions"],[0,"(A) In general"],[2,"Paragraph (1) shall not apply to an alien if the Attorney General determines that—"],[3,"(i) the alien ordered, incited, assisted, or otherwise participated in the persecution of any person on account of race, religion, nationality, membership in a particular social group, or political opinion;"],[3,"(ii) the alien, having been convicted by a final judgment of a particularly serious crime, constitutes a danger to the community of the United States;"],[3,"(iii) there are serious reasons for believing that the alien has committed a serious nonpolitical crime outside the United States prior to the arrival of the alien in the United States;"],[3,"(iv) there are reasonable grounds for regarding the alien as a danger to the security of the United States;"],[3,"(v) the alien is described in subclause (I), (II), (III), (IV), or (VI) of section 1182(a)(3)(B)(i) of this title or section 1227(a)(4)(B) of this title (relating to terrorist activity), unless, in the case only of an alien described in subclause (IV) of section 1182(a)(3)(B)(i) of this title, the Attorney General determines, in the Attorney General's discretion, that there are not reasonable grounds for regarding the alien as a danger to the security of the United States; or"],[3,"(vi) the alien was firmly resettled in another country prior to arriving in the United States."],[0,"(B) Special rules"],[0,"(i) Conviction of aggravated felony"],[3,"For purposes of clause (ii) of subparagraph (A), an alien who has been convicted of an aggravated felony shall be considered to have been convicted of a particularly serious crime."],[0,"(ii) Offenses"],[3,"The Attorney General may designate by regulation offenses that will be considered to be a crime described in clause (ii) or (iii) of subparagraph (A)."],[0,"(C) Additional limitations"],[2,"The Attorney General may by regulation establish additional limitations and conditions, consistent with this section, under which an alien shall be ineligible for asylum under paragraph (1)."],[0,"(D) No judicial review"],[2,"There shall be no judicial review of a determination of the Attorney General under subparagraph (A)(v)."],[0,"(3) Treatment of spouse and children"],[0,"(A) In general"],[2,"A spouse or child (as defined in section 1101(b)(1)(A), (B), (C), (D), or (E) of this title) of an alien who is granted asylum under this subsection may, if not otherwise eligible for asylum under this section, be granted the same status as the alien if accompanying, or following to join, such alien."],[0,"(B) Continued classification of certain aliens as children"],[2,"An unmarried alien who seeks to accompany, or follow to join, a parent granted asylum under this subsection, and who was under 21 years of age on the date on which such parent applied for asylum under this section, shall continue to be classified as a child for purposes of this paragraph and section 1159(b)(3) of this title, if the alien attained 21 years of age after such application was filed but while it was pending."],[0,"(C) Initial jurisdiction"],[2,"An asylum officer (as defined in section 1225(b)(1)(E) of this title) shall have initial jurisdiction over any asylum application filed by an unaccompanied alien child (as defined in section 279(g) of title 6), regardless of whether filed in accordance with this section or section 1225(b) of this title."],[0,"(c) Asylum status"],[0,"(1) In general"],[1,"In the case of an alien granted asylum under subsection (b), the Attorney General—"],[2,"(A) shall not remove or return the alien to the alien's country of nationality or, in the case of a person having no nationality, the country of the alien's last habitual residence;"],[2,"(B) shall authorize the alien to engage in employment in the United States and provide the alien with appropriate endorsement of that authorization; and"],[2,"(C) may allow the alien to travel abroad with the prior consent of the Attorney General."],[0,"(2) Termination of asylum"],[1,"Asylum granted under subsection (b) does not convey a right to remain permanently in the United States, and may be terminated if the Attorney General determines that—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1158?type=usc&year=mostrecent&link-type=html"},"head":"§1158. Asylum","tname":"Aliens and Nationality","by":{"0":"4, 31, 36, 6, 37, 37, 6, 37, 6, 37, 4, 26, 5, 24, 42, 6, 6, 31, 36, 37, 6, 31, 37, 6, 31, 26, 42, 31","1":"3, 13, 3, 13, 4, 4, 4, 4, 8, 19, 21, 24, 25, 4, 10, 16, 17, 20, 21, 16, 4, 16, 4, 16","2":"14"}},{"t":"usc","label":"8 U.S.C. § 1159","url":"https://www.law.cornell.edu/uscode/text/8/1159","subs":["(a)","(a)(1)","(a)(1)(A)","(a)(2)","(b)","(b)(2)","(b)(3)","(b)(5)","(c)","(b)(1988)"],"stext":{"head":"§1159. Adjustment of status of refugees","paras":[[0,"(a) Inspection and examination by Department of Homeland Security"],[0,"(1) Any alien who has been admitted to the United States under section 1157 of this title—"],[1,"(A) whose admission has not been terminated by the Secretary of Homeland Security or the Attorney General pursuant to such regulations as the Secretary of Homeland Security or the Attorney General may prescribe,"],[1,"(B) who has been physically present in the United States for at least one year, and"],[1,"(C) who has not acquired permanent resident status,"],[0,"shall, at the end of such year period, return or be returned to the custody of the Department of Homeland Security for inspection and examination for admission to the United States as an immigrant in accordance with the provisions of sections 1225, 1229a, and 1231 of this title."],[0,"(2) Any alien who is found upon inspection and examination by an immigration officer pursuant to paragraph (1) or after a hearing before an immigration judge to be admissible (except as otherwise provided under subsection (c)) as an immigrant under this chapter at the time of the alien's inspection and examination shall, notwithstanding any numerical limitation specified in this chapter, be regarded as lawfully admitted to the United States for permanent residence as of the date of such alien's arrival into the United States."],[0,"(b) Requirements for adjustment"],[0,"The Secretary of Homeland Security or the Attorney General, in the Secretary's or the Attorney General's discretion and under such regulations as the Secretary or the Attorney General may prescribe, may adjust to the status of an alien lawfully admitted for permanent residence the status of any alien granted asylum who—"],[1,"(1) applies for such adjustment,"],[1,"(2) has been physically present in the United States for at least one year after being granted asylum,"],[1,"(3) continues to be a refugee within the meaning of section 1101(a)(42)(A) of this title or a spouse or child of such a refugee,"],[1,"(4) is not firmly resettled in any foreign country, and"],[1,"(5) is admissible (except as otherwise provided under subsection (c)) as an immigrant under this chapter at the time of examination for adjustment of such alien."],[0,"Upon approval of an application under this subsection, the Secretary of Homeland Security or the Attorney General shall establish a record of the alien's admission for lawful permanent residence as of the date one year before the date of the approval of the application."],[0,"(c) Coordination with section 1182"],[0,"The provisions of paragraphs (4), (5), and (7)(A) of section 1182(a) of this title shall not be applicable to any alien seeking adjustment of status under this section, and the Secretary of Homeland Security or the Attorney General may waive any other provision of such section (other than paragraph (2)(C) or subparagraph (A), (B), (C), or (E) of paragraph (3)) with respect to such an alien for humanitarian purposes, to assure family unity, or when it is otherwise in the public interest."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1159?type=usc&year=mostrecent&link-type=html"},"head":"§1159. Adjustment of status of refugees","tname":"Aliens and Nationality","by":{"0":"13, 38, 5, 21, 29, 5, 21, 2, 5, 14, 18, 25, 13-14, 21, 23, 29, 38, 7, 13, 21, 23, 5, 23","1":"37, 37, 23, 18, 2-25, 27-29, 31-34, 36-39, 16, 17, 26, 23, 26, 27, 37, 23, 5, 8, 25, 22","2":"4, 5, 1, 2, 12, 14, 15, 18, 19, 3, 4, 5, 14, 17, 4, 5, 17, 6, 7, 8, 17"}},{"t":"usc","label":"8 U.S.C. § 1182","url":"https://www.law.cornell.edu/uscode/text/8/1182","subs":["(a)","(a)(1)","(a)(3)(D)","(a)(19)(1982)","(n)(4)(E)(ii)"],"stext":{"head":"§1182. Inadmissible aliens","paras":[[0,"(a) Classes of aliens ineligible for visas or admission"],[0,"Except as otherwise provided in this chapter, aliens who are inadmissible under the following paragraphs are ineligible to receive visas and ineligible to be admitted to the United States:"],[0,"(1) Health-related grounds"],[0,"(A) In general"],[2,"Any alien—"],[3,"(i) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services) to have a communicable disease of public health significance; 1"],[3,"(ii) except as provided in subparagraph (C), who seeks admission as an immigrant, or who seeks adjustment of status to the status of an alien lawfully admitted for permanent residence, and who has failed to present documentation of having received vaccination against vaccine-preventable diseases, which shall include at least the following diseases: mumps, measles, rubella, polio, tetanus and diphtheria toxoids, pertussis, influenza type B and hepatitis B, and any other vaccinations against vaccine-preventable diseases recommended by the Advisory Committee for Immunization Practices,"],[3,"(iii) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services in consultation with the Attorney General)—"],[4,"(I) to have a physical or mental disorder and behavior associated with the disorder that may pose, or has posed, a threat to the property, safety, or welfare of the alien or others, or"],[4,"(II) to have had a physical or mental disorder and a history of behavior associated with the disorder, which behavior has posed a threat to the property, safety, or welfare of the alien or others and which behavior is likely to recur or to lead to other harmful behavior, or"],[3,"(iv) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services) to be a drug abuser or addict,"],[2,"is inadmissible."],[0,"(B) Waiver authorized"],[2,"For provision authorizing waiver of certain clauses of subparagraph (A), see subsection (g)."],[0,"(C) Exception from immunization requirement for adopted children 10 years of age or younger"],[2,"Clause (ii) of subparagraph (A) shall not apply to a child who—"],[3,"(i) is 10 years of age or younger,"],[3,"(ii) is described in subparagraph (F) or (G) of section 1101(b)(1) of this title; 1 and"],[3,"(iii) is seeking an immigrant visa as an immediate relative under section 1151(b) of this title,"],[2,"if, prior to the admission of the child, an adoptive parent or prospective adoptive parent of the child, who has sponsored the child for admission as an immediate relative, has executed an affidavit stating that the parent is aware of the provisions of subparagraph (A)(ii) and will ensure that, within 30 days of the child's admission, or at the earliest time that is medically appropriate, the child will receive the vaccinations identified in such subparagraph."],[0,"(2) Criminal and related grounds"],[0,"(A) Conviction of certain crimes"],[0,"(i) In general"],[3,"Except as provided in clause (ii), any alien convicted of, or who admits having committed, or who admits committing acts which constitute the essential elements of—"],[4,"(I) a crime involving moral turpitude (other than a purely political offense) or an attempt or conspiracy to commit such a crime, or"],[4,"(II) a violation of (or a conspiracy or attempt to violate) any law or regulation of a State, the United States, or a foreign country relating to a controlled substance (as defined in section 802 of title 21),"],[0,"is inadmissible."],[0,"(ii) Exception"],[3,"Clause (i)(I) shall not apply to an alien who committed only one crime if—"],[4,"(I) the crime was committed when the alien was under 18 years of age, and the crime was committed (and the alien released from any confinement to a prison or correctional institution imposed for the crime) more than 5 years before the date of application for a visa or other documentation and the date of application for admission to the United States, or"],[4,"(II) the maximum penalty possible for the crime of which the alien was convicted (or which the alien admits having committed or of which the acts that the alien admits having committed constituted the essential elements) did not exceed imprisonment for one year and, if the alien was convicted of such crime, the alien was not sentenced to a term of imprisonment in excess of 6 months (regardless of the extent to which the sentence was ultimately executed)."],[0,"(B) Multiple criminal convictions"],[2,"Any alien convicted of 2 or more offenses (other than purely political offenses), regardless of whether the conviction was in a single trial or whether the offenses arose from a single scheme of misconduct and regardless of whether the offenses involved moral turpitude, for which the aggregate sentences to confinement were 5 years or more is inadmissible."],[0,"(C) Controlled substance traffickers"],[2,"Any alien who the consular officer or the Attorney General knows or has reason to believe—"],[3,"(i) is or has been an illicit trafficker in any controlled substance or in any listed chemical (as defined in section 802 of title 21), or is or has been a knowing aider, abettor, assister, conspirator, or colluder with others in the illicit trafficking in any such controlled or listed substance or chemical, or endeavored to do so; or"],[3,"(ii) is the spouse, son, or daughter of an alien inadmissible under clause (i), has, within the previous 5 years, obtained any financial or other benefit from the illicit activity of that alien, and knew or reasonably should have known that the financial or other benefit was the product of such illicit activity,"],[2,"is inadmissible."],[0,"(D) Prostitution and commercialized vice"],[2,"Any alien who—"],[3,"(i) is coming to the United States solely, principally, or incidentally to engage in prostitution, or has engaged in prostitution within 10 years of the date of application for a visa, admission, or adjustment of status,"],[3,"(ii) directly or indirectly procures or attempts to procure, or (within 10 years of the date of application for a visa, admission, or adjustment of status) procured or attempted to procure or to import, prostitutes or persons for the purpose of prostitution, or receives or (within such 10-year period) received, in whole or in part, the proceeds of prostitution, or"],[3,"(iii) is coming to the United States to engage in any other unlawful commercialized vice, whether or not related to prostitution,"],[2,"is inadmissible."],[0,"(E) Certain aliens involved in serious criminal activity who have asserted immunity from prosecution"],[2,"Any alien—"],[3,"(i) who has committed in the United States at any time a serious criminal offense (as defined in section 1101(h) of this title),"],[3,"(ii) for whom immunity from criminal jurisdiction was exercised with respect to that offense,"],[3,"(iii) who as a consequence of the offense and exercise of immunity has departed from the United States, and"],[3,"(iv) who has not subsequently submitted fully to the jurisdiction of the court in the United States having jurisdiction with respect to that offense,"],[2,"is inadmissible."],[0,"(F) Waiver authorized"],[2,"For provision authorizing waiver of certain subparagraphs of this paragraph, see subsection (h)."],[0,"(G) Foreign government officials who have committed particularly severe violations of religious freedom"],[2,"Any alien who, while serving as a foreign government official, was responsible for or directly carried out, at any time, particularly severe violations of religious freedom, as defined in section 6402 of title 22, is inadmissible."],[0,"(H) Significant traffickers in persons"],[0,"(i) In general"],[3,"Any alien who commits or conspires to commit human trafficking offenses in the United States or outside the United States, or who the consular officer, the Secretary of Homeland Security, the Secretary of State, or the Attorney General knows or has reason to believe is or has been a knowing aider, abettor, assister, conspirator, or colluder with such a trafficker in severe forms of trafficking in persons, as defined in the section 7102 of title 22, is inadmissible."],[0,"(ii) Beneficiaries of trafficking"],[3,"Except as provided in clause (iii), any alien who the consular officer or the Attorney General knows or has reason to believe is the spouse, son, or daughter of an alien inadmissible under clause (i), has, within the previous 5 years, obtained any financial or other benefit from the illicit activity of that alien, and knew or reasonably should have known that the financial or other benefit was the product of such illicit activity, is inadmissible."],[0,"(iii) Exception for certain sons and daughters"],[3,"Clause (ii) shall not apply to a son or daughter who was a child at the time he or she received the benefit described in such clause."],[0,"(I) Money laundering"],[2,"Any alien—"],[3,"(i) who a consular officer or the Attorney General knows, or has reason to believe, has engaged, is engaging, or seeks to enter the United States to engage, in an offense which is described in section 1956 or 1957 of title 18 (relating to laundering of monetary instruments); or"],[3,"(ii) who a consular officer or the Attorney General knows is, or has been, a knowing aider, abettor, assister, conspirator, or colluder with others in an offense which is described in such section;"],[2,"is inadmissible."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1182?type=usc&year=mostrecent&link-type=html"},"head":"§1182. Inadmissible aliens","tname":"Aliens and Nationality","by":{"0":"24, 24, 24","2":"17, 3"}},{"t":"usc","label":"8 U.S.C. § 1229b","url":"https://www.law.cornell.edu/uscode/text/8/1229b","subs":["(b)(1)"],"stext":{"head":"§1229b. Cancellation of removal; adjustment of status","paras":[[0,"(a) Cancellation of removal for certain permanent residents"],[0,"The Attorney General may cancel removal in the case of an alien who is inadmissible or deportable from the United States if the alien—"],[1,"(1) has been an alien lawfully admitted for permanent residence for not less than 5 years,"],[1,"(2) has resided in the United States continuously for 7 years after having been admitted in any status, and"],[1,"(3) has not been convicted of any aggravated felony."],[0,"(b) Cancellation of removal and adjustment of status for certain nonpermanent residents"],[0,"(1) In general"],[1,"The Attorney General may cancel removal of, and adjust to the status of an alien lawfully admitted for permanent residence, an alien who is inadmissible or deportable from the United States if the alien—"],[2,"(A) has been physically present in the United States for a continuous period of not less than 10 years immediately preceding the date of such application;"],[2,"(B) has been a person of good moral character during such period;"],[2,"(C) has not been convicted of an offense under section 1182(a)(2), 1227(a)(2), or 1227(a)(3) of this title, subject to paragraph (5); and"],[2,"(D) establishes that removal would result in exceptional and extremely unusual hardship to the alien's spouse, parent, or child, who is a citizen of the United States or an alien lawfully admitted for permanent residence."],[0,"(2) Special rule for battered spouse or child"],[0,"(A) Authority"],[2,"The Attorney General may cancel removal of, and adjust to the status of an alien lawfully admitted for permanent residence, an alien who is inadmissible or deportable from the United States if the alien demonstrates that—"],[3,"(i)(I) the alien has been battered or subjected to extreme cruelty by a spouse or parent who is or was a United States citizen (or is the parent of a child of a United States citizen and the child has been battered or subjected to extreme cruelty by such citizen parent);"],[3,"(II) the alien has been battered or subjected to extreme cruelty by a spouse or parent who is or was a lawful permanent resident (or is the parent of a child of an alien who is or was a lawful permanent resident and the child has been battered or subjected to extreme cruelty by such permanent resident parent); or"],[3,"(III) the alien has been battered or subjected to extreme cruelty by a United States citizen or lawful permanent resident whom the alien intended to marry, but whose marriage is not legitimate because of that United States citizen's or lawful permanent resident's bigamy;"],[3,"(ii) the alien has been physically present in the United States for a continuous period of not less than 3 years immediately preceding the date of such application, and the issuance of a charging document for removal proceedings shall not toll the 3-year period of continuous physical presence in the United States;"],[3,"(iii) the alien has been a person of good moral character during such period, subject to the provisions of subparagraph (C);"],[3,"(iv) the alien is not inadmissible under paragraph (2) or (3) of section 1182(a) of this title, is not deportable under paragraphs (1)(G) or (2) through (4) of section 1227(a) of this title, subject to paragraph (5), and has not been convicted of an aggravated felony; and"],[3,"(v) the removal would result in extreme hardship to the alien, the alien's child, or the alien's parent."],[0,"(B) Physical presence"],[2,"Notwithstanding subsection (d)(2), for purposes of subparagraph (A)(ii) or for purposes of section 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996), an alien shall not be considered to have failed to maintain continuous physical presence by reason of an absence if the alien demonstrates a connection between the absence and the battering or extreme cruelty perpetrated against the alien. No absence or portion of an absence connected to the battering or extreme cruelty shall count toward the 90-day or 180-day limits established in subsection (d)(2). If any absence or aggregate absences exceed 180 days, the absences or portions of the absences will not be considered to break the period of continuous presence. Any such period of time excluded from the 180-day limit shall be excluded in computing the time during which the alien has been physically present for purposes of the 3-year requirement set forth in this subparagraph, subparagraph (A)(ii), and section 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996)."],[0,"(C) Good moral character"],[2,"Notwithstanding section 1101(f) of this title, an act or conviction that does not bar the Attorney General from granting relief under this paragraph by reason of subparagraph (A)(iv) shall not bar the Attorney General from finding the alien to be of good moral character under subparagraph (A)(iii) or section 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996), if the Attorney General finds that the act or conviction was connected to the alien's having been battered or subjected to extreme cruelty and determines that a waiver is otherwise warranted."],[0,"(D) Credible evidence considered"],[2,"In acting on applications under this paragraph, the Attorney General shall consider any credible evidence relevant to the application. The determination of what evidence is credible and the weight to be given that evidence shall be within the sole discretion of the Attorney General."],[0,"(3) Recordation of date"],[1,"With respect to aliens who the Attorney General adjusts to the status of an alien lawfully admitted for permanent residence under paragraph (1) or (2), the Attorney General shall record the alien's lawful admission for permanent residence as of the date of the Attorney General's cancellation of removal under paragraph (1) or (2)."],[0,"(4) Children of battered aliens and parents of battered alien children"],[0,"(A) In general"],[2,"The Attorney General shall grant parole under section 1182(d)(5) of this title to any alien who is a—"],[3,"(i) child of an alien granted relief under section 1229b(b)(2) or 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996); or"],[3,"(ii) parent of a child alien granted relief under section 1229b(b)(2) or 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996)."],[0,"(B) Duration of parole"],[2,"The grant of parole shall extend from the time of the grant of relief under subsection (b)(2) or section 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996) to the time the application for adjustment of status filed by aliens covered under this paragraph has been finally adjudicated. Applications for adjustment of status filed by aliens covered under this paragraph shall be treated as if the applicants were VAWA self-petitioners. Failure by the alien granted relief under subsection (b)(2) or section 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996) to exercise due diligence in filing a visa petition on behalf of an alien described in clause (i) or (ii) may result in revocation of parole."],[0,"(5) Application of domestic violence waiver authority"],[1,"The authority provided under section 1227(a)(7) of this title may apply under paragraphs (1)(B), (1)(C), and (2)(A)(iv) in a cancellation of removal and adjustment of status proceeding."],[0,"(6) Relatives of trafficking victims"],[0,"(A) In general"],[2,"Upon written request by a law enforcement official, the Secretary of Homeland Security may parole under section 1182(d)(5) of this title any alien who is a relative of an alien granted continued presence under section 7105(c)(3)(A) of title 22, if the relative—"],[3,"(i) was, on the date on which law enforcement applied for such continued presence—"],[4,"(I) in the case of an alien granted continued presence who is under 21 years of age, the spouse, child, parent, or unmarried sibling under 18 years of age, of the alien; or"],[4,"(II) in the case of an alien granted continued presence who is 21 years of age or older, the spouse or child of the alien; or"],[3,"(ii) is a parent or sibling of the alien who the requesting law enforcement official, in consultation with the Secretary of Homeland Security, as appropriate, determines to be in present danger of retaliation as a result of the alien's escape from the severe form of trafficking or cooperation with law enforcement, irrespective of age."],[0,"(B) Duration of parole"],[0,"(i) In general"],[3,"The Secretary may extend the parole granted under subparagraph (A) until the final adjudication of the application filed by the principal alien under section 1101(a)(15)(T)(ii) of this title."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1229b?type=usc&year=mostrecent&link-type=html"},"head":"§1229b. Cancellation of removal; adjustment of status","tname":"Aliens and Nationality","by":{"0":"20, 42","1":"22","2":"14"}},{"t":"usc","label":"8 U.S.C. § 1231","url":"https://www.law.cornell.edu/uscode/text/8/1231","subs":["(b)(3)","(b)(3)(B)"],"by":{"0":"42, 36"}},{"t":"usc","label":"8 U.S.C. § 1254a","url":"https://www.law.cornell.edu/uscode/text/8/1254a","subs":["(a)(1)(A)"],"by":{"0":"19"}},{"t":"usc","label":"8 U.S.C. § 1255","url":"https://www.law.cornell.edu/uscode/text/8/1255","subs":["(c)","(a)(1952)","(a)(1958)","(a)","(i)","(i)(1)","(c)(2)"],"stext":{"head":"§1255. Adjustment of status of nonimmigrant to that of person admitted for permanent residence","paras":[[0,"(a) Status as person admitted for permanent residence on application and eligibility for immigrant visa"],[0,"The status of an alien who was inspected and admitted or paroled into the United States or the status of any other alien having an approved petition for classification as a VAWA self-petitioner may be adjusted by the Attorney General, in his discretion and under such regulations as he may prescribe, to that of an alien lawfully admitted for permanent residence if (1) the alien makes an application for such adjustment, (2) the alien is eligible to receive an immigrant visa and is admissible to the United States for permanent residence, and (3) an immigrant visa is immediately available to him at the time his application is filed."],[0,"(b) Record of lawful admission for permanent residence; reduction of preference visas"],[0,"Upon the approval of an application for adjustment made under subsection (a), the Attorney General shall record the alien's lawful admission for permanent residence as of the date the order of the Attorney General approving the application for the adjustment of status is made, and the Secretary of State shall reduce by one the number of the preference visas authorized to be issued under sections 1152 and 1153 of this title within the class to which the alien is chargeable for the fiscal year then current."],[0,"(c) Alien crewmen, aliens continuing or accepting unauthorized employment, and aliens admitted in transit without visa"],[0,"Other than an alien having an approved petition for classification as a VAWA self-petitioner, subsection (a) shall not be applicable to (1) an alien crewman; (2) subject to subsection (k), an alien (other than an immediate relative as defined in section 1151(b) of this title or a special immigrant described in section 1101(a)(27)(H), (I), (J), or (K) of this title) who hereafter continues in or accepts unauthorized employment prior to filing an application for adjustment of status or who is in unlawful immigration status on the date of filing the application for adjustment of status or who has failed (other than through no fault of his own or for technical reasons) to maintain continuously a lawful status since entry into the United States; (3) any alien admitted in transit without visa under section 1182(d)(4)(C) of this title; (4) an alien (other than an immediate relative as defined in section 1151(b) of this title) who was admitted as a nonimmigrant visitor without a visa under section 1182(l) of this title or section 1187 of this title; (5) an alien who was admitted as a nonimmigrant described in section 1101(a)(15)(S) of this title,1 (6) an alien who is deportable under section 1227(a)(4)(B) of this title; (7) any alien who seeks adjustment of status to that of an immigrant under section 1153(b) of this title and is not in a lawful nonimmigrant status; or (8) any alien who was employed while the alien was an unauthorized alien, as defined in section 1324a(h)(3) of this title, or who has otherwise violated the terms of a nonimmigrant visa."],[0,"(d) Alien admitted for permanent residence on conditional basis; fiancee or fiance of citizen"],[0,"The Attorney General may not adjust, under subsection (a), the status of an alien lawfully admitted to the United States for permanent residence on a conditional basis under section 1186a of this title. The Attorney General may not adjust, under subsection (a), the status of a nonimmigrant alien described in section 1101(a)(15)(K) of this title except to that of an alien lawfully admitted to the United States on a conditional basis under section 1186a of this title as a result of the marriage of the nonimmigrant (or, in the case of a minor child, the parent) to the citizen who filed the petition to accord that alien's nonimmigrant status under section 1101(a)(15)(K) of this title."],[0,"(e) Restriction on adjustment of status based on marriages entered while in admissibility or deportation proceedings; bona fide marriage exception"],[0,"(1) Except as provided in paragraph (3), an alien who is seeking to receive an immigrant visa on the basis of a marriage which was entered into during the period described in paragraph (2) may not have the alien's status adjusted under subsection (a)."],[0,"(2) The period described in this paragraph is the period during which administrative or judicial proceedings are pending regarding the alien's right to be admitted or remain in the United States."],[0,"(3) Paragraph (1) and section 1154(g) of this title shall not apply with respect to a marriage if the alien establishes by clear and convincing evidence to the satisfaction of the Attorney General that the marriage was entered into in good faith and in accordance with the laws of the place where the marriage took place and the marriage was not entered into for the purpose of procuring the alien's admission as an immigrant and no fee or other consideration was given (other than a fee or other consideration to an attorney for assistance in preparation of a lawful petition) for the filing of a petition under section 1154(a) of this title or subsection (d) or (p) 2 of section 1184 of this title with respect to the alien spouse or alien son or daughter. In accordance with regulations, there shall be only one level of administrative appellate review for each alien under the previous sentence."],[0,"(f) Limitation on adjustment of status"],[0,"The Attorney General may not adjust, under subsection (a), the status of an alien lawfully admitted to the United States for permanent residence on a conditional basis under section 1186b of this title."],[0,"(g) Special immigrants"],[0,"In applying this section to a special immigrant described in section 1101(a)(27)(K) of this title, such an immigrant shall be deemed, for purposes of subsection (a), to have been paroled into the United States."],[0,"(h) Application with respect to special immigrants"],[0,"In applying this section to a special immigrant described in section 1101(a)(27)(J) of this title—"],[1,"(1) such an immigrant shall be deemed, for purposes of subsection (a), to have been paroled into the United States; and"],[1,"(2) in determining the alien's admissibility as an immigrant—"],[2,"(A) paragraphs (4), (5)(A), (6)(A), (6)(C), (6)(D), (7)(A), and (9)(B) of section 1182(a) of this title shall not apply; and"],[2,"(B) the Attorney General may waive other paragraphs of section 1182(a) of this title (other than paragraphs (2)(A), (2)(B), (2)(C) (except for so much of such paragraph as related to a single offense of simple possession of 30 grams or less of marijuana), (3)(A), (3)(B), (3)(C), and (3)(E)) in the case of individual aliens for humanitarian purposes, family unity, or when it is otherwise in the public interest."],[0,"The relationship between an alien and the alien's natural parents or prior adoptive parents shall not be considered a factor in making a waiver under paragraph (2)(B). Nothing in this subsection or section 1101(a)(27)(J) of this title shall be construed as authorizing an alien to apply for admission or be admitted to the United States in order to obtain special immigrant status described in such section."],[0,"(i) Adjustment in status of certain aliens physically present in United States"],[0,"(1) Notwithstanding the provisions of subsections (a) and (c) of this section, an alien physically present in the United States—"],[1,"(A) who—"],[2,"(i) entered the United States without inspection; or"],[2,"(ii) is within one of the classes enumerated in subsection (c) of this section;"],[1,"(B) who is the beneficiary (including a spouse or child of the principal alien, if eligible to receive a visa under section 1153(d) of this title) of—"],[2,"(i) a petition for classification under section 1154 of this title that was filed with the Attorney General on or before April 30, 2001; or"],[2,"(ii) an application for a labor certification under section 1182(a)(5)(A) of this title that was filed pursuant to the regulations of the Secretary of Labor on or before such date; and"],[1,"(C) who, in the case of a beneficiary of a petition for classification, or an application for labor certification, described in subparagraph (B) that was filed after January 14, 1998, is physically present in the United States on December 21, 2000;"],[0,"may apply to the Attorney General for the adjustment of his or her status to that of an alien lawfully admitted for permanent residence. The Attorney General may accept such application only if the alien remits with such application a sum equalling $1,000 as of the date of receipt of the application, but such sum shall not be required from a child under the age of seventeen, or an alien who is the spouse or unmarried child of an individual who obtained temporary or permanent resident status under section 1160 or 1255a of this title or section 202 of the Immigration Reform and Control Act of 1986 at any date, who—"],[1,"(i) as of May 5, 1988, was the unmarried child or spouse of the individual who obtained temporary or permanent resident status under section 1160 or 1255a of this title or section 202 of the Immigration Reform and Control Act of 1986;"],[1,"(ii) entered the United States before May 5, 1988, resided in the United States on May 5, 1988, and is not a lawful permanent resident; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1255?type=usc&year=mostrecent&link-type=html"},"head":"§1255. Adjustment of status of nonimmigrant to that of person admitted for permanent residence","tname":"Aliens and Nationality","by":{"0":"27, 19","1":"13, 30, 30, 30, 14, 30, 14, 14","2":"15, 14, 14, 14"}},{"t":"usc","label":"8 U.S.C. § 1255a","url":"https://www.law.cornell.edu/uscode/text/8/1255a","subs":["(a)","(a)(2)","(h)(3)(A)(iii)"],"stext":{"head":"§1255a. Adjustment of status of certain entrants before January 1, 1982, to that of person admitted for lawful residence","paras":[[0,"(a) Temporary resident status"],[0,"The Attorney General shall adjust the status of an alien to that of an alien lawfully admitted for temporary residence if the alien meets the following requirements:"],[0,"(1) Timely application"],[0,"(A) During application period"],[2,"Except as provided in subparagraph (B), the alien must apply for such adjustment during the 12-month period beginning on a date (not later than 180 days after November 6, 1986) designated by the Attorney General."],[0,"(B) Application within 30 days of show-cause order"],[2,"An alien who, at any time during the first 11 months of the 12-month period described in subparagraph (A), is the subject of an order to show cause issued under section 1252 of this title (as in effect before October 1, 1996), must make application under this section not later than the end of the 30-day period beginning either on the first day of such 12-month period or on the date of the issuance of such order, whichever day is later."],[0,"(C) Information included in application"],[2,"Each application under this subsection shall contain such information as the Attorney General may require, including information on living relatives of the applicant with respect to whom a petition for preference or other status may be filed by the applicant at any later date under section 1154(a) of this title."],[0,"(2) Continuous unlawful residence since 1982"],[0,"(A) In general"],[2,"The alien must establish that he entered the United States before January 1, 1982, and that he has resided continuously in the United States in an unlawful status since such date and through the date the application is filed under this subsection."],[0,"(B) Nonimmigrants"],[2,"In the case of an alien who entered the United States as a nonimmigrant before January 1, 1982, the alien must establish that the alien's period of authorized stay as a nonimmigrant expired before such date through the passage of time or the alien's unlawful status was known to the Government as of such date."],[0,"(C) Exchange visitors"],[2,"If the alien was at any time a nonimmigrant exchange alien (as defined in section 1101(a)(15)(J) of this title), the alien must establish that the alien was not subject to the two-year foreign residence requirement of section 1182(e) of this title or has fulfilled that requirement or received a waiver thereof."],[0,"(3) Continuous physical presence since November 6, 1986"],[0,"(A) In general"],[2,"The alien must establish that the alien has been continuously physically present in the United States since November 6, 1986."],[0,"(B) Treatment of brief, casual, and innocent absences"],[2,"An alien shall not be considered to have failed to maintain continuous physical presence in the United States for purposes of subparagraph (A) by virtue of brief, casual, and innocent absences from the United States."],[0,"(C) Admissions"],[2,"Nothing in this section shall be construed as authorizing an alien to apply for admission to, or to be admitted to, the United States in order to apply for adjustment of status under this subsection."],[0,"(4) Admissible as immigrant"],[1,"The alien must establish that he—"],[2,"(A) is admissible to the United States as an immigrant, except as otherwise provided under subsection (d)(2),"],[2,"(B) has not been convicted of any felony or of three or more misdemeanors committed in the United States,"],[2,"(C) has not assisted in the persecution of any person or persons on account of race, religion, nationality, membership in a particular social group, or political opinion, and"],[2,"(D) is registered or registering under the Military Selective Service Act [50 U.S.C. 3801 et seq.], if the alien is required to be so registered under that Act."],[1,"For purposes of this subsection, an alien in the status of a Cuban and Haitian entrant described in paragraph (1) or (2)(A) of section 501(e) of Public Law 96–422 [8 U.S.C. 1522 note] shall be considered to have entered the United States and to be in an unlawful status in the United States."],[0,"(b) Subsequent adjustment to permanent residence and nature of temporary resident status"],[0,"(1) Adjustment to permanent residence"],[1,"The Attorney General shall adjust the status of any alien provided lawful temporary resident status under subsection (a) to that of an alien lawfully admitted for permanent residence if the alien meets the following requirements:"],[0,"(A) Timely application after one year's residence"],[2,"The alien must apply for such adjustment during the 2-year period beginning with the nineteenth month that begins after the date the alien was granted such temporary resident status."],[0,"(B) Continuous residence"],[0,"(i) In general"],[3,"The alien must establish that he has continuously resided in the United States since the date the alien was granted such temporary resident status."],[0,"(ii) Treatment of certain absences"],[3,"An alien shall not be considered to have lost the continuous residence referred to in clause (i) by reason of an absence from the United States permitted under paragraph (3)(A)."],[0,"(C) Admissible as immigrant"],[2,"The alien must establish that he—"],[3,"(i) is admissible to the United States as an immigrant, except as otherwise provided under subsection (d)(2), and"],[3,"(ii) has not been convicted of any felony or three or more misdemeanors committed in the United States."],[0,"(D) Basic citizenship skills"],[0,"(i) In general"],[3,"The alien must demonstrate that he either—"],[4,"(I) meets the requirements of section 1423(a) of this title (relating to minimal understanding of ordinary English and a knowledge and understanding of the history and government of the United States), or"],[4,"(II) is satisfactorily pursuing a course of study (recognized by the Attorney General) to achieve such an understanding of English and such a knowledge and understanding of the history and government of the United States."],[0,"(ii) Exception for elderly or developmentally disabled individuals"],[3,"The Attorney General may, in his discretion, waive all or part of the requirements of clause (i) in the case of an alien who is 65 years of age or older or who is developmentally disabled."],[0,"(iii) Relation to naturalization examination"],[3,"In accordance with regulations of the Attorney General, an alien who has demonstrated under clause (i)(I) that the alien meets the requirements of section 1423(a) of this title may be considered to have satisfied the requirements of that section for purposes of becoming naturalized as a citizen of the United States under subchapter III."],[0,"(2) Termination of temporary residence"],[1,"The Attorney General shall provide for termination of temporary resident status granted an alien under subsection (a)—"],[2,"(A) if it appears to the Attorney General that the alien was in fact not eligible for such status;"],[2,"(B) if the alien commits an act that (i) makes the alien inadmissible to the United States as an immigrant, except as otherwise provided under subsection (d)(2), or (ii) is convicted of any felony or three or more misdemeanors committed in the United States; or"],[2,"(C) at the end of the 43rd month beginning after the date the alien is granted such status, unless the alien has filed an application for adjustment of such status pursuant to paragraph (1) and such application has not been denied."],[0,"(3) Authorized travel and employment during temporary residence"],[1,"During the period an alien is in lawful temporary resident status granted under subsection (a)—"],[0,"(A) Authorization of travel abroad"],[2,"The Attorney General shall, in accordance with regulations, permit the alien to return to the United States after such brief and casual trips abroad as reflect an intention on the part of the alien to adjust to lawful permanent resident status under paragraph (1) and after brief temporary trips abroad occasioned by a family obligation involving an occurrence such as the illness or death of a close relative or other family need."],[0,"(B) Authorization of employment"],[2,"The Attorney General shall grant the alien authorization to engage in employment in the United States and provide to that alien an \"employment authorized\" endorsement or other appropriate work permit."],[0,"(c) Applications for adjustment of status"],[0,"(1) To whom may be made"],[1,"The Attorney General shall provide that applications for adjustment of status under subsection (a) may be filed—"],[2,"(A) with the Attorney General, or"],[2,"(B) with a qualified designated entity, but only if the applicant consents to the forwarding of the application to the Attorney General."],[1,"As used in this section, the term \"qualified designated entity\" means an organization or person designated under paragraph (2)."],[0,"(2) Designation of qualified entities to receive applications"],[1,"For purposes of assisting in the program of legalization provided under this section, the Attorney General—"],[2,"(A) shall designate qualified voluntary organizations and other qualified State, local, and community organizations, and"],[2,"(B) may designate such other persons as the Attorney General determines are qualified and have substantial experience, demonstrated competence, and traditional long-term involvement in the preparation and submittal of applications for adjustment of status under section 1159 or 1255 of this title, Public Law 89–732 [8 U.S.C. 1255 note], or Public Law 95–145 [8 U.S.C. 1255 note]."],[0,"(3) Treatment of applications by designated entities"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1255a?type=usc&year=mostrecent&link-type=html"},"head":"§1255a. Adjustment of status of certain entrants before January 1, 1982, to that of person admitted for lawful residence","tname":"Aliens and Nationality","by":{"0":"19, 20","1":"22, 22","2":"15"}},{"t":"usc","label":"8 U.S.C. § 1255b","url":"https://www.law.cornell.edu/uscode/text/8/1255b","subs":["(a)"],"stext":{"head":"§1255b. Adjustment of status of certain nonimmigrants to that of persons admitted for permanent residence","paras":[[0,"Notwithstanding any other provision of law—"],[0,"(a) Application"],[0,"Any alien admitted to the United States as a nonimmigrant under the provisions of either section 101(a)(15)(A)(i) or (ii) or 101(a)(15)(G)(i) or (ii) of the Immigration and Nationality Act [8 U.S.C. 1101(a)(15)(A)(i), (ii), (G)(i), (ii)], who has failed to maintain a status under any of those provisions, may apply to the Attorney General for adjustment of his status to that of an alien lawfully admitted for permanent residence."],[0,"(b) Record of admission"],[0,"If, after consultation with the Secretary of State, it shall appear to the satisfaction of the Attorney General that the alien has shown compelling reasons demonstrating both that the alien is unable to return to the country represented by the government which accredited the alien or the member of the alien's immediate family and that adjustment of the alien's status to that of an alien lawfully admitted for permanent residence would be in the national interest, that the alien is a person of good moral character, that he is admissible for permanent residence under the Immigration and Nationality Act [8 U.S.C. 1101 et seq.], and that such action would not be contrary to the national welfare, safety, or security, the Attorney General, in his discretion, may record the alien's lawful admission for permanent residence as of the date the order of the Attorney General approving the application for adjustment of status is made."],[0,"(c) Report to the Congress; resolution not favoring adjustment of status; reduction of quota"],[0,"A complete and detailed statement of the facts and pertinent provisions of law in the case shall be reported to the Congress with the reasons for such adjustment of status. Such reports shall be submitted on the first day of each calendar month in which Congress is in session. The Secretary of State shall, if the alien was classifiable as a quota immigrant at the time of his entry, reduce by one the quota of the quota area to which the alien is chargeable under section 202 of the Immigration and Nationality Act [8 U.S.C. 1152] for the fiscal year then current or the next following year in which a quota is available. No quota shall be so reduced by more than 50 per centum in any fiscal year."],[0,"(d) Limitations"],[0,"The number of aliens who may be granted the status of aliens lawfully admitted for permanent residence in any fiscal year, pursuant to this section, shall not exceed fifty."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1255b?type=usc&year=mostrecent&link-type=html"},"head":"§1255b. Adjustment of status of certain nonimmigrants to that of persons admitted for permanent residence","tname":"Aliens and Nationality","by":{"0":"20","1":"22, 22","2":"6, 14"}},{"t":"usc","label":"18 U.S.C. § 1964","url":"https://www.law.cornell.edu/uscode/text/18/1964","subs":["(c)"],"by":{"0":"17"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"38 U.S.C. § 1112","url":"https://www.law.cornell.edu/uscode/text/38/1112","subs":["(c)(1)"],"by":{"0":"17"}},{"t":"law","label":"Pub. L. No. 82-414","url":"https://www.govinfo.gov/link/statute/66/163","by":{"0":"27","2":"13"}},{"t":"law","label":"Pub. L. No. 85-700","url":"https://www.govinfo.gov/link/statute/72/699","by":{"0":"28"}},{"t":"law","label":"Pub. L. No. 96-212","url":"https://www.govinfo.gov/link/statute/94/102","by":{"0":"3, 6, 25, 28-30, 35","1":"3, 11, 20","2":"16"}},{"t":"law","label":"Pub. L. No. 99-603","url":"https://www.govinfo.gov/link/statute/100/3359","by":{"0":"30, 31"}},{"t":"law","label":"Pub. L. No. 101-649","url":"https://www.govinfo.gov/link/statute/104/4978","by":{"0":"33, 35","1":"18, 25","2":"4, 18, 19"}},{"t":"law","label":"Page(s), Pub. L. No. 104-208","url":"https://www.govinfo.gov/link/plaw/104/public/208","by":{"0":"6, 31","1":"33"}},{"t":"law","label":"Pub. L. No. 109-13","url":"https://www.govinfo.gov/link/plaw/109/public/13","by":{"0":"36"}},{"t":"reg","label":"8 C.F.R. § 1208.16","url":"https://www.ecfr.gov/current/title-8/section-1208.16","subs":["(c)"],"by":{"0":"42"}},{"t":"reg","label":"8 C.F.R. § 1208.24","url":"https://www.ecfr.gov/current/title-8/section-1208.24","subs":["(a)","(c)","(d)","(e)","(f)"],"by":{"0":"42, 42, 6, 37, 42, 42","2":"7, 8"}},{"t":"reg","label":"OTHER AUTHORITIES, 90 Fed. Reg. 30076","url":"https://www.govinfo.gov/link/fr/90/30076","by":{"0":"37"}},{"t":"reg","label":"90 Fed. Reg. 31670","url":"https://www.govinfo.gov/link/fr/90/31670","by":{"0":"37"}},{"t":"reg","label":"90 Fed. Reg. 42597","url":"https://www.govinfo.gov/link/fr/90/42597","by":{"0":"37"}},{"t":"reg","label":"90 Fed. Reg. 51376","url":"https://www.govinfo.gov/link/fr/90/51376","by":{"0":"37"}},{"t":"case","label":"Alberta Gas Chems., Ltd. v. Cenalese Corp.","cite":"650 F.2d 9","y":1981,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/650/9/","by":{"1":"32"}},{"t":"case","label":"American Trucking Ass’ns v. Frisco Transp. Co.","cite":"358 U.S. 133","y":1958,"id":"1958/15","sc":1,"sum":"The Commission's order is sustained. Pp. 134-146. (1) On the record in this case, the Commission properly concluded that the omission from the certificates of the reservation of power to impose restrictions wag not due to a conscious policy choice on the part of the Commission but resulted from an inadvertent ministerial error on the part of the Commission's staff Pp. 140-144. (2) Under § 17 (3) of the Act, the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"32"}},{"t":"case","label":"Branch v. Smith","cite":"538 U.S. 254","y":2003,"id":"2002/01-1437","sc":1,"sum":"The Court held, 9-0, that the District Court properly enjoined enforcement of the state- court plan that lacked the required timely preclearance.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"City & County of San Francisco v. EPA","cite":"604 U.S. 334","y":2025,"url":"https://supreme.justia.com/cases/federal/us/604/334/","sc":1,"by":{"1":"21"}},{"t":"case","label":"Department of Agric. Rural Dev. Rural Hous. Serv. v. Kirtz","cite":"601 U.S. 42","y":2024,"id":"2023/22-846","sc":1,"sum":"A consumer may sue a federal agency under 15 U. S. C. §§1681n and 1681o for defying the terms of the Fair Credit Reporting Act.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"23"}},{"t":"case","label":"Dubin v. United States","cite":"599 U.S. 110","y":2023,"id":"2022/22-10","sc":1,"sum":"Under 18 U. S. C. §1028A(a)(1)’s crime of “aggravated identity theft,” a defendant “uses” another person’s means of identification “in relation to” a predicate offense when the use is at the crux of what makes the conduct criminal.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"18"}},{"t":"case","label":"EB5 Holdings Inc. v. Edlow","cite":"166 F.4th 1106","y":2026,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/166/1106/","by":{"1":"17"}},{"t":"case","label":"Freeman v. Quicken Loans, Inc.","cite":"566 U.S. 624","y":2012,"id":"2011/10-1042","sc":1,"sum":"The Court held that Section 8(b) of the Real Estate Settlement Procedures Act prohibits a real estate service provider from charging an unearned fee if the fee is divided between two or more parties.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"Hewitt v. United States","cite":"606 U.S. 419","y":2025,"id":"2024/23-1002","sc":1,"sum":"Because a sentence “has . . . been imposed” for purposes of §403(b) of the First Step Act only if the sentence is extant (i.e., has not been vacated), the Act’s more lenient penalties apply to defendants whose previous 18 U. S. C. §924(c) sentences have been vacated and who need to be resentenced following the Act’s enactment; the judgment of the Fifth Circuit is reversed and the case is remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"15"}},{"t":"case","label":"Mazaleski v. Treusdell","cite":"562 F.2d 701","y":1977,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/562/701/","by":{"1":"32"}},{"t":"case","label":"Patel v. Garland","cite":"596 U.S. 328","y":2022,"id":"2021/20-979","sc":1,"sum":"Federal courts lack jurisdiction to review facts found as part of any judgment relating to the granting of discretionary-relief in immigration proceedings enumerated under 8 U. S. C. §1252(a)(2)(B)(i).","sumSrc":"Holding (supremecourt.gov)","by":{"1":"21, 38"}},{"t":"case","label":"Pugin v. Garland","cite":"599 U.S. 600","y":2023,"id":"2022/22-23","sc":1,"sum":"An offense may “relate to” obstruction of justice under the Immigration and Nationality Act’s definition of an “aggravated felony,” 8 U. S. C. §1101(a)(43)(S), even if the offense does not require that an investigation or proceeding be pending.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"40","2":"22"}},{"t":"case","label":"Swan & Finch Co. v. United States","cite":"190 U.S. 143","y":1903,"id":"scdb/1902-178","sc":1,"sum":"The placing on hoard vessels in the United States and bound for foreign ports of lubricating oils manufactured from imported rape seed on which duty has been paid and which oils are for use in, and to be consumed by the vessels is not such an exportation of the oils as entitles the sellers to drawbacks under § 22 of the act of August 28, 1894, reenacted as § 30 of the act of July 27, 1897.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"39","2":"22"}},{"t":"case","label":"Tapia v. United States","cite":"564 U.S. 319","y":2011,"id":"2010/10-5400","sc":1,"sum":"The Court held that a district court may not give a defendant a longer prison sentence based on speculation about if and when the defendant would be able to participate in an inmate drug rehabilitation program.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"United States v. Manzi","cite":"276 U.S. 463","y":1928,"id":"scdb/1927-168","sc":1,"sum":"1. The widow of an alien who died after declaring his intention to become a citizen but before completing his naturalization, must, in order to obtain the statutory benefit of his declaration, file her petition for naturalization not less than two nor more than seven years after the date of her deceased husband's declaration of intention.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"39, 40","2":"22"}},{"t":"case","label":"United States Postal Serv. v. Konan","cite":"607 U.S. 391","y":2026,"id":"2025/24-351","sc":1,"sum":"The United States retains sovereign immunity for claims arising out of the intentional nondelivery of mail because both “miscarriage” and “loss” of mail under the Federal Tort Claims Act’s postal exception, 28 U. S. C. §2680(b), can occur as a result of the Postal Service’s intentional failure to deliver the mail.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"16"}},{"t":"case","label":"Utility Air Regulatory Grp. v. EPA","cite":"573 U.S. 302","y":2014,"id":"2013/12-1146","sc":1,"sum":"The Court held that, under the Clean Air Act, the EPA is not required to include greenhouse gas emissions every time it mentions air pollution.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Watson v. Republican Nat’l Comm.","cite":"146 S. Ct. 2165","y":2026,"id":"2025/24-1260","sc":1,"sum":"The federal election-day statutes—3 U. S. C. §1, 2 U. S. C. §§ 1, 7—do not prevent Mississippi from counting absentee ballots postmarked by election day but received up to five days thereafter; nothing in the federal election-day statutes requires ballots to be received by election day.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"29"}},{"t":"case","label":"West Va. Univ. Hosps., Inc. v. Casey","cite":"499 U.S. 83","y":1991,"id":"1990/89-994","sc":1,"sum":"Fees for services rendered by experts in civil rights litigation may not be shifted to the losing party as part of \"a reasonable attorney's fee\" under § 1988.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"29"}},{"t":"usc","label":"8 U.S.C. § 1427","url":"https://www.law.cornell.edu/uscode/text/8/1427","subs":["(a)"],"by":{"1":"38"}},{"t":"usc","label":"19 U.S.C. § 1641","url":"https://www.law.cornell.edu/uscode/text/19/1641","subs":["(c)(1)","(a)(1)","(b)(1)"],"stext":{"head":"§1641. Customs brokers","paras":[[0,"(a) Definitions"],[0,"As used in this section:"],[1,"(1) The term \"customs broker\" means any person granted a customs broker's license by the Secretary under subsection (b)."],[1,"(2) The term \"customs business\" means those activities involving transactions with U.S. Customs and Border Protection concerning the entry and admissibility of merchandise, its classification and valuation, the payment of duties, taxes, or other charges assessed or collected by U.S. Customs and Border Protection upon merchandise by reason of its importation, or the refund, rebate, or drawback thereof. It also includes the preparation of documents or forms in any format and the electronic transmission of documents, invoices, bills, or parts thereof, intended to be filed with U.S. Customs and Border Protection in furtherance of such activities, whether or not signed or filed by the preparer, or activities relating to such preparation, but does not include the mere electronic transmission of data received for transmission to Customs."],[1,"(3) The term \"Secretary\" means the Secretary of the Treasury."],[0,"(b) Customs broker's licenses"],[0,"(1) In general"],[1,"No person may conduct customs business (other than solely on behalf of that person) unless that person holds a valid customs broker's license issued by the Secretary under paragraph (2) or (3)."],[0,"(2) Licenses for individuals"],[1,"The Secretary may grant an individual a customs broker's license only if that individual is a citizen of the United States. Before granting the license, the Secretary may require an applicant to show any facts deemed necessary to establish that the applicant is of good moral character and qualified to render valuable service to others in the conduct of customs business. In assessing the qualifications of an applicant, the Secretary may conduct an examination to determine the applicant's knowledge of customs and related laws, regulations and procedures, bookkeeping, accounting, and all other appropriate matters."],[0,"(3) Licenses for corporations, etc."],[1,"The Secretary may grant a customs broker's license to any corporation, association, or partnership that is organized or existing under the laws of any of the several States of the United States if at least one officer of the corporation or association, or one member of the partnership, holds a valid customs broker's license granted under paragraph (2)."],[0,"(4) Duties"],[1,"A customs broker shall exercise responsible supervision and control over the customs business that it conducts."],[0,"(5) Lapse of license"],[1,"The failure of a customs broker that is licensed as a corporation, association, or partnership under paragraph (3) to have, for any continuous period of 120 days, at least one officer of the corporation or association, or at least one member of the partnership, validly licensed under paragraph (2) shall, in addition to causing the broker to be subject to any other sanction under this section (including paragraph (6)), result in the revocation by operation of law of its license."],[0,"(6) Prohibited acts"],[1,"Any person who intentionally transacts customs business, other than solely on the behalf of that person, without holding a valid customs broker's license granted to that person under this subsection shall be liable to the United States for a monetary penalty not to exceed $10,000 for each such transaction as well as for each violation of any other provision of this section. This penalty shall be assessed in the same manner and under the same procedures as the monetary penalties provided for in subsection (d)(2)(A)."],[0,"(c) Customs broker's permits"],[0,"(1) In general"],[1,"Each person granted a customs broker's license under subsection (b) shall be issued, in accordance with such regulations as the Secretary shall prescribe, either or both of the following:"],[2,"(A) A national permit for the conduct of such customs business as the Secretary prescribes by regulation."],[2,"(B) A permit for each customs district in which that person conducts customs business and, except as provided in paragraph (2), regularly employs at least 1 individual who is licensed under subsection (b)(2) to exercise responsible supervision and control over the customs business conducted by that person in that district."],[0,"(2) Exception"],[1,"If a person granted a customs broker's license under subsection (b) can demonstrate to the satisfaction of the Secretary that—"],[2,"(A) he regularly employs in the region in which that district is located at least one individual who is licensed under subsection (b)(2), and"],[2,"(B) that sufficient procedures exist within the company for the person employed in that region to exercise responsible supervision and control over the customs business conducted by that person in that district,"],[1,"the Secretary may waive the requirement in paragraph (1)(B)."],[0,"(3) Lapse of permit"],[1,"The failure of a customs broker granted a permit under paragraph (1) to employ, for any continuous period of 180 days, at least one individual who is licensed under subsection (b)(2) within the district or region (if paragraph (2) applies) for which a permit was issued shall, in addition to causing the broker to be subject to any other sanction under this section (including any in subsection (d)), result in the revocation by operation of law of the permit."],[0,"(4) Appointment of subagents"],[1,"Notwithstanding subsection (c)(1), upon the implementation by the Secretary under section 1413(b)(2) of this title of the component of the National Customs Automation Program referred to in section 1411(a)(2)(B) of this title, a licensed broker may appoint another licensed broker holding a permit in a customs district to act on its behalf as its subagent in that district if such activity relates to the filing of information that is permitted by law or regulation to be filed electronically. A licensed broker appointing a subagent pursuant to this paragraph shall remain liable for any and all obligations arising under bond and any and all duties, taxes, and fees, as well as any other liabilities imposed by law, and shall be precluded from delegating to a subagent such liability."],[0,"(d) Disciplinary proceedings"],[0,"(1) General rule"],[1,"The Secretary may impose a monetary penalty in all cases with the exception of the infractions described in clause (iii) of subparagraph (B) of this subsection, or revoke or suspend a license or permit of any customs broker, if it is shown that the broker—"],[2,"(A) has made or caused to be made in any application for any license or permit under this section, or report filed with U.S. Customs and Border Protection, any statement which was, at the time and in light of the circumstances under which it was made, false or misleading with respect to any material fact, or has omitted to state in any such application or report any material fact which was required to be stated therein;"],[2,"(B) has been convicted at any time after the filing of an application for license under subsection (b) of any felony or misdemeanor which the Secretary finds—"],[3,"(i) involved the importation or exportation of merchandise;"],[3,"(ii) arose out of the conduct of its customs business; or"],[3,"(iii) involved larceny, theft, robbery, extortion, forgery, counterfeiting, fraudulent concealment, embezzlement, fraudulent conversion, or misappropriation of funds;"],[2,"(C) has violated any provision of any law enforced by U.S. Customs and Border Protection or the rules or regulations issued under any such provision;"],[2,"(D) has counseled, commanded, induced, procured, or knowingly aided or abetted the violations by any other person of any provision of any law enforced by U.S. Customs and Border Protection, or the rules or regulations issued under any such provision;"],[2,"(E) has knowingly employed, or continues to employ, any person who has been convicted of a felony, without written approval of such employment from the Secretary;"],[2,"(F) has, in the course of its customs business, with intent to defraud, in any manner willfully and knowingly deceived, misled or threatened any client or prospective client; or"],[2,"(G) has been convicted of committing or conspiring to commit an act of terrorism described in section 2332b of title 18."],[0,"(2) Procedures"],[0,"(A) Monetary penalty"],[2,"Unless action has been taken under subparagraph (B), the appropriate customs officer shall serve notice in writing upon any customs broker to show cause why the broker should not be subject to a monetary penalty not to exceed $30,000 in total for a violation or violations of this section. The notice shall advise the customs broker of the allegations or complaints against him and shall explain that the broker has a right to respond to the allegations or complaints in writing within 30 days of the date of the notice. Before imposing a monetary penalty, the customs officer shall consider the allegations or complaints and any timely response made by the customs broker and issue a written decision. A customs broker against whom a monetary penalty has been issued under this section shall have a reasonable opportunity under section 1618 of this title to make representations seeking remission or mitigation of the monetary penalty. Following the conclusion of any proceeding under section 1618 of this title, the appropriate customs officer shall provide to the customs broker a written statement which sets forth the final determination and the findings of fact and conclusions of law on which such determination is based."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/19/1641?type=usc&year=mostrecent&link-type=html"},"head":"§1641. Customs brokers","tname":"Customs Duties","by":{"1":"14","2":"9, 9"}},{"t":"usc","label":"21 U.S.C. § 360j","url":"https://www.law.cornell.edu/uscode/text/21/360j","subs":["(m)(5)"],"stext":{"head":"§360j. General provisions respecting control of devices intended for human use","paras":[[0,"(a) General rule"],[0,"Any requirement authorized by or under section 351, 352, 360, or 360i of this title applicable to a device intended for human use shall apply to such device until the applicability of the requirement to the device has been changed by action taken under section 360c, 360d, or 360e of this title or under subsection (g) of this section, and any requirement established by or under section 351, 352, 360, or 360i of this title which is inconsistent with a requirement imposed on such device under section 360d or 360e of this title or under subsection (g) of this section shall not apply to such device."],[0,"(b) Custom devices"],[0,"(1) In general"],[1,"The requirements of sections 360d and 360e of this title shall not apply to a device that—"],[2,"(A) is created or modified in order to comply with the order of an individual physician or dentist (or any other specially qualified person designated under regulations promulgated by the Secretary after an opportunity for an oral hearing);"],[2,"(B) in order to comply with an order described in subparagraph (A), necessarily deviates from an otherwise applicable performance standard under section 360d of this title or requirement under section 360e of this title;"],[2,"(C) is not generally available in the United States in finished form through labeling or advertising by the manufacturer, importer, or distributor for commercial distribution;"],[2,"(D) is designed to treat a unique pathology or physiological condition that no other device is domestically available to treat;"],[2,"(E)(i) is intended to meet the special needs of such physician or dentist (or other specially qualified person so designated) in the course of the professional practice of such physician or dentist (or other specially qualified person so designated); or"],[2,"(ii) is intended for use by an individual patient named in such order of such physician or dentist (or other specially qualified person so designated);"],[2,"(F) is assembled from components or manufactured and finished on a case-by-case basis to accommodate the unique needs of individuals described in clause (i) or (ii) of subparagraph (E); and"],[2,"(G) may have common, standardized design characteristics, chemical and material compositions, and manufacturing processes as commercially distributed devices."],[0,"(2) Limitations"],[1,"Paragraph (1) shall apply to a device only if—"],[2,"(A) such device is for the purpose of treating a sufficiently rare condition, such that conducting clinical investigations on such device would be impractical;"],[2,"(B) production of such device under paragraph (1) is limited to no more than 5 units per year of a particular device type, provided that such replication otherwise complies with this section; and"],[2,"(C) the manufacturer of such device notifies the Secretary on an annual basis, in a manner prescribed by the Secretary, of the manufacture of such device."],[0,"(3) Guidance"],[1,"Not later than 2 years after July 9, 2012, the Secretary shall issue final guidance on replication of multiple devices described in paragraph (2)(B)."],[0,"(c) Trade secrets"],[0,"Any information reported to or otherwise obtained by the Secretary or his representative under section 360c, 360d, 360e, 360f, 360h, 360i, or 374 of this title or under subsection (f) or (g) of this section which is exempt from disclosure pursuant to subsection (a) of section 552 of title 5 by reason of subsection (b)(4) of such section shall be considered confidential and shall not be disclosed and may not be used by the Secretary as the basis for the reclassification of a device from class III to class II or class I or as the basis for the establishment or amendment of a performance standard under section 360d of this title for a device reclassified from class III to class II, except (1) in accordance with subsection (h), and (2) that such information may be disclosed to other officers or employees concerned with carrying out this chapter or when relevant in any proceeding under this chapter (other than section 360c or 360d of this title)."],[0,"(d) Notices and findings"],[0,"Each notice of proposed rulemaking under section 360c, 360d, 360e, 360f, 360h, or 360i of this title, or under this section, any other notice which is published in the Federal Register with respect to any other action taken under any such section and which states the reasons for such action, and each publication of findings required to be made in connection with rulemaking under any such section shall set forth—"],[1,"(1) the manner in which interested persons may examine data and other information on which the notice or findings is based, and"],[1,"(2) the period within which interested persons may present their comments on the notice or findings (including the need therefor) orally or in writing, which period shall be at least sixty days but may not exceed ninety days unless the time is extended by the Secretary by a notice published in the Federal Register stating good cause therefor."],[0,"(e) Restricted devices"],[0,"(1) The Secretary may by regulation require that a device be restricted to sale, distribution, or use—"],[1,"(A) only upon the written or oral authorization of a practitioner licensed by law to administer or use such device, or"],[1,"(B) upon such other conditions as the Secretary may prescribe in such regulation,"],[0,"if, because of its potentiality for harmful effect or the collateral measures necessary to its use, the Secretary determines that there cannot otherwise be reasonable assurance of its safety and effectiveness. No condition prescribed under subparagraph (B) may restrict the use of a device to persons with specific training or experience in its use or to persons for use in certain facilities unless the Secretary determines that such a restriction is required for the safe and effective use of the device. No such condition may exclude a person from using a device solely because the person does not have the training or experience to make him eligible for certification by a certifying board recognized by the American Board of Medical Specialties or has not been certified by such a Board. A device subject to a regulation under this subsection is a restricted device."],[0,"(2) The label of a restricted device shall bear such appropriate statements of the restrictions required by a regulation under paragraph (1) as the Secretary may in such regulation prescribe."],[0,"(f) Good manufacturing practice requirements"],[0,"(1)(A) The Secretary may, in accordance with subparagraph (B), prescribe regulations requiring that the methods used in, and the facilities and controls used for, the manufacture, pre-production design validation (including a process to assess the performance of a device but not including an evaluation of the safety or effectiveness of a device), packing, storage, and installation of a device conform to current good manufacturing practice, as prescribed in such regulations, to assure that the device will be safe and effective and otherwise in compliance with this chapter."],[0,"(B) Before the Secretary may promulgate any regulation under subparagraph (A) he shall—"],[1,"(i) afford the advisory committee established under paragraph (3) an opportunity to submit recommendations to him with respect to the regulation proposed to be promulgated;"],[1,"(ii) afford opportunity for an oral hearing; and"],[1,"(iii) ensure that such regulation conforms, to the extent practicable, with internationally recognized standards defining quality systems, or parts of the standards, for medical devices."],[0,"The Secretary shall provide the advisory committee a reasonable time to make its recommendation with respect to proposed regulations under subparagraph (A)."],[0,"(2)(A) Any person subject to any requirement prescribed by regulations under paragraph (1) may petition the Secretary for an exemption or variance from such requirement. Such a petition shall be submitted to the Secretary in such form and manner as he shall prescribe and shall—"],[1,"(i) in the case of a petition for an exemption from a requirement, set forth the basis for the petitioner's determination that compliance with the requirement is not required to assure that the device will be safe and effective and otherwise in compliance with this chapter,"],[1,"(ii) in the case of a petition for a variance from a requirement, set forth the methods proposed to be used in, and the facilities and controls proposed to be used for, the manufacture, packing, storage, and installation of the device in lieu of the methods, facilities, and controls prescribed by the requirement, and"],[1,"(iii) contain such other information as the Secretary shall prescribe."],[0,"(B) The Secretary may refer to the advisory committee established under paragraph (3) any petition submitted under subparagraph (A). The advisory committee shall report its recommendations to the Secretary with respect to a petition referred to it within sixty days of the date of the petition's referral. Within sixty days after—"],[1,"(i) the date the petition was submitted to the Secretary under subparagraph (A), or"],[1,"(ii) if the petition was referred to an advisory committee, the expiration of the sixty-day period beginning on the date the petition was referred to the advisory committee,"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/360j?type=usc&year=mostrecent&link-type=html"},"head":"§360j. General provisions respecting control of devices intended for human use","tname":"Food and Drugs","by":{"1":"14","2":"9"}},{"t":"usc","label":"51 U.S.C. § 20134","url":"https://www.law.cornell.edu/uscode/text/51/20134","stext":{"head":"§20134. Arrest authority","paras":[[0,"Under regulations prescribed by the Administrator and approved by the Attorney General, employees of the Administration and of its contractors and subcontractors authorized to carry firearms under section 20133 of this title may arrest without warrant for any offense against the United States committed in their presence, or for any felony cognizable under the laws of the United States if they have reasonable grounds to believe that the person to be arrested has committed or is committing such felony. Persons granted authority to make arrests by this section may exercise that authority only while guarding and protecting property owned or leased by, or under the control of, the United States under the administration and control of the Administration or one of its contractors or subcontractors, at facilities owned by or contracted to the Administration."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/51/20134?type=usc&year=mostrecent&link-type=html"},"head":"§20134. Arrest authority","tname":"National and Commercial Space Programs","by":{"1":"14","2":"10"}},{"t":"reg","label":"45 Fed. Reg. 37,392","url":"https://www.govinfo.gov/link/fr/45/37392","by":{"1":"34"}},{"t":"case","label":"Advocate Health Care Network v. Stapleton","cite":"581 U.S. 468","y":2017,"id":"2016/16-74","sc":1,"sum":"The Court determined that the “church plan” exemption of the Employee Retirement Income Security Act of 1974 (ERISA) applies to plans that are maintained by a qualifying church-affiliated organization, even if that organization did not originally establish the plan.","sumSrc":"Oyez","by":{"2":"5"}},{"t":"case","label":"Bernal v. NRA Group, LLC","cite":"930 F.3d 891","y":2019,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/930/891/","by":{"2":"13"}},{"t":"case","label":"Chun v. Sava","cite":"708 F.2d 869","y":1983,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/708/869/","by":{"2":"6"}},{"t":"case","label":"Fernandez-Roque v. Smith","cite":"539 F. Supp. 925","y":1982,"court":"N.D. Ga.","url":"https://www.courtlistener.com/c/F.%20Supp./539/925/","by":{"2":"6"}},{"t":"case","label":"Moskal v. United States","cite":"498 U.S. 103","y":1990,"id":"1990/89-964","sc":1,"sum":"A person who receives genuine vehicle titles, knowing that they incorporate fraudulently tendered odometer readings, receives those titles knowing them to have been \"falsely made\" in violation of § 2314.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"23"}},{"t":"case","label":"Mullin v. Al Otro Lado","cite":"609 U.S. 258","y":2026,"url":"https://supreme.justia.com/cases/federal/us/609/258/","sc":1,"by":{"2":"5"}},{"t":"case","label":"Robleto-Pastora v. Holder","cite":"591 F.3d 1051","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/591/1051/","by":{"2":"21"}},{"t":"case","label":"United States v. Craft","cite":"535 U.S. 274","y":2002,"id":"2001/00-1831","sc":1,"sum":"The Court held that each tenant possesses individual rights in the estate sufficient to constitute \"property\" or \"rights to property\" for the purposes of the lien.","sumSrc":"Oyez","by":{"2":"20"}},{"t":"case","label":"United States v. Estate of Romani","cite":"523 U.S. 517","y":1998,"id":"1997/96-1613","sc":1,"sum":"The Court held that section 3713(a) does not require that a federal tax claim be given preference over a judgment creditor's perfected lien on real property.","sumSrc":"Oyez","by":{"2":"20"}},{"t":"case","label":"Page(s) Watson v. Republican National Committee","cite":"609 U.S. 672","y":2026,"url":"https://supreme.justia.com/cases/federal/us/609/672/","sc":1,"by":{"2":"20"}},{"t":"case","label":"Wooden v. United States","cite":"595 U.S. 360","y":2022,"id":"2021/20-5279","sc":1,"sum":"Wooden’s ten burglary offenses arising from a single criminal episode did not occur on different “occasions” and thus count as only one prior conviction under the Armed Career Criminal Act.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"23"}},{"t":"usc","label":"2 U.S.C. § 185","url":"https://www.law.cornell.edu/uscode/text/2/185","subs":["(d)(3)(E)"],"by":{"2":"10"}},{"t":"usc","label":"8 U.S.C. § 1184","url":"https://www.law.cornell.edu/uscode/text/8/1184","subs":["(a)(1)"],"by":{"2":"6"}},{"t":"usc","label":"8 U.S.C. § 1203","url":"https://www.law.cornell.edu/uscode/text/8/1203","subs":["(b)"],"by":{"2":"6"}},{"t":"usc","label":"8 U.S.C. § 1251","url":"https://www.law.cornell.edu/uscode/text/8/1251","subs":["(a)(9)"],"by":{"2":"6"}},{"t":"usc","label":"8 U.S.C. § 1252","url":"https://www.law.cornell.edu/uscode/text/8/1252","subs":["(e)(2)(C)"],"by":{"2":"4, 10, 15"}},{"t":"usc","label":"8 U.S.C. § 1258","url":"https://www.law.cornell.edu/uscode/text/8/1258","by":{"2":"6"}},{"t":"usc","label":"8 U.S.C. § 1364","url":"https://www.law.cornell.edu/uscode/text/8/1364","subs":["(b)(1)"],"by":{"2":"4"}},{"t":"usc","label":"8 U.S.C. § 1613","url":"https://www.law.cornell.edu/uscode/text/8/1613","subs":["(b)(1)(B)"],"by":{"2":"3"}},{"t":"usc","label":"8 U.S.C. § 1641","url":"https://www.law.cornell.edu/uscode/text/8/1641","subs":["(b)(2)"],"by":{"2":"10"}},{"t":"usc","label":"15 U.S.C. § 2603","url":"https://www.law.cornell.edu/uscode/text/15/2603","subs":["(c)(3)(A)"],"by":{"2":"10"}},{"t":"usc","label":"44 U.S.C. § 3903","url":"https://www.law.cornell.edu/uscode/text/44/3903","subs":["(c)(5)"],"by":{"2":"10"}},{"t":"law","label":"Pub. L. No. 97-35","url":"https://www.govinfo.gov/link/statute/95/357","by":{"2":"6"}},{"t":"reg","label":"8 C.F.R. § 108.1","url":"https://www.ecfr.gov/current/title-8/section-108.1","by":{"2":"6"}},{"t":"reg","label":"8 C.F.R. § 208.15","url":"https://www.ecfr.gov/current/title-8/section-208.15","subs":["(a)(2)","(a)(3)"],"by":{"2":"16, 17"}},{"t":"reg","label":"8 C.F.R. § 208.24","url":"https://www.ecfr.gov/current/title-8/section-208.24","subs":["(c)"],"by":{"2":"7"}},{"t":"reg","label":"OTHER AUTHORITIES, 44 Fed. Reg. 21,253","url":"https://www.govinfo.gov/link/fr/44/21253","by":{"2":"6"}}]};